1	/**
2	 * RuntimeObserverDispatcher —— engine 级共享 MutationObserver 分发器（ADR-0003 决策 7）。
3	 *
4	 * 取代此前每条 runtime 指令各自建 observer 的做法（如 loading.ts 旧版的 static initialize）：
5	 * 在 `engine.el` 上建**单一** MutationObserver，attributeFilter 为全部 runtime 指令属性名的并集，
6	 * 把 childList 增/删与 attributes 变化路由到对应指令类的 `mounted`/`unmounted`/`attrChanged`，
7	 * 并广播 `directive/<name>/{mounted|unmounted|attr-changed}` 事件。
8	 *
9	 * **实例化工厂沿用** runtime 标准模式：`new Cls(engine, undefined, info)` + `inst.el = el` + `inst.mounted()`
10	 * （见 base.ts 构造函数；Runtime 实例无 scope/binding）。
11	 *
12	 * **仅处理 `DirectiveKind.Runtime`**（Hybrid 当前不存在，按 YAGNI 暂不处理，留扩展口）。
13	 *
14	 * **已知限制（与旧 loading observer 一致，刻意保留）**：attributeFilter 只含裸属性 `x-<name>`，
15	 * 故修饰符形式（如 `x-loading.screen`）的运行时**值变化**不触发 attrChanged；其增/删仍生效。
16	 */
17	import type { AutoSpark } from "../../engine";
18	import { DirectiveKind, AutoSparkDirectiveBase, type RuntimeDirective } from "../base";
19	import { getDirectives } from "../utils/getDirectives";
20	
21	/** runtime 指令注册条目：类引用 + 裸属性名 + 匹配属性变体的正则 */
22	interface RuntimeEntry {
23	    Cls: typeof AutoSparkDirectiveBase;
24	    /** 裸属性名 `x-<name>`，用于 attributeFilter 与 hasAttribute 判定 */
25	    attr: string;
26	    /** 匹配 `x-<name>` 及修饰符形式 `x-<name>.<mod>`，`.` 边界避免误匹配 `x-<name>-state` */
27	    attrRe: RegExp;
28	}
29	
30	export class RuntimeObserverDispatcher {
31	    readonly engine: AutoSpark<any>;
32	    /** name → 注册条目 */
33	    private registry = new Map<string, RuntimeEntry>();
34	    /** name → (el → 实例)；一个元素可挂多个 runtime 指令 */
35	    private instances = new Map<string, Map<HTMLElement, AutoSparkDirectiveBase>>();
36	    private mo: MutationObserver | undefined;
37	    /**
38	     * slot 盲区根集合（ADR-0006 决策 8）：x-slot 宿主登记于此。
39	     * 盲区内子树的 runtime 指令（如 child engine 写入的 x-loading）由 child engine 自身 dispatcher
40	     * 负责，父 dispatcher 对其**致盲**——避免父/子双 dispatcher 抢管同一节点、重复 mount。
41	     */
42	    private slotRoots = new Set<HTMLElement>();
43	
44	    constructor(engine: AutoSpark<any>) {
45	        this.engine = engine;
46	    }
47	
48	    /**
49	     * 启动：枚举 engine.directives 中 `kind===Runtime` 的类建 registry，连 observer，初始扫描。
50	     *
51	     * 须在 `initializeAll()`（含各指令的 injectStyles 等 FOUC 防御副作用）**之后**调用——
52	     * 初始扫描会同步触发首次 mounted → mountOverlay，依赖样式已注入。
53	     */
54	    start(): void {
55	        for (const [name, Cls] of this.engine.directives) {
56	            if (Cls.kind === DirectiveKind.Runtime) this._register(name, Cls);
57	        }
58	        this._buildObserver();
59	        // 初始扫描：编译产物中已存在的静态 runtime 指令元素（同步触发 mounted，首屏立即可见）
60	        for (const [el, names] of this.collectEls(this.engine.el)) {
61	            for (const name of names) this.mount(el, name);
62	        }
63	    }
64	
65	    /** 晚注册的 runtime 指令（DirectiveManager.set 触发）：入 registry → 重建 observer → 重扫该属性 */
66	    onDirectiveRegistered(name: string, Cls: typeof AutoSparkDirectiveBase): void {
67	        if (this.registry.has(name)) return;
68	        this._register(name, Cls);
69	        this._buildObserver();
70	        for (const [el, names] of this.collectEls(this.engine.el)) {
71	            if (names.includes(name)) this.mount(el, name);
72	        }
73	    }
74	
75	    private _register(name: string, Cls: typeof AutoSparkDirectiveBase): void {
76	        const attr = `x-${name}`;
77	        this.registry.set(name, { Cls, attr, attrRe: new RegExp(`^x-${name}(\\.|$)`) });
78	    }
79	
80	    /**
81	     * 登记 slot 盲区根（x-slot 宿主）。盲区内子树不参与本 dispatcher 的 mount/attr 派发。
82	     * 由 SlotDirective.created() 调用；对称地在 destroy() 经 removeSlotRoot 注销。
83	     */
84	    addSlotRoot(el: HTMLElement): void {
85	        this.slotRoots.add(el);
86	    }
87	
88	    /** 注销 slot 盲区根（SlotDirective.destroy() 调用）。 */
89	    removeSlotRoot(el: HTMLElement): void {
90	        this.slotRoots.delete(el);
91	    }
92	
93	    /**
94	     * 元素是否落在任一 slot 盲区的**严格后代**子树内（不含盲区根本身）。
95	     * 无盲区时短路返回 false（热路径零开销）。用于 collectEls / _handle 过滤掉 child engine 管辖的子树。
96	     *
97	     * **不含盲区根本身**：slot 宿主自身的 runtime 指令（如 fetch 期间 x-slot 添加的 `x-loading`）
98	     * 仍归本 dispatcher 管理与 mount；仅其**子树**（child engine 编译产物）致盲，避免双 dispatcher 抢管。
99	     */
100	    private _inSlotRoot(el: HTMLElement): boolean {
101	        if (this.slotRoots.size === 0) return false;
102	        for (const root of this.slotRoots) {
103	            if (root !== el && root.contains(el)) return true;
104	        }
105	        return false;
106	    }
107	
108	    /** （重建）共享 observer：attributeFilter 为全部 runtime 裸属性并集 */
109	    private _buildObserver(): void {
110	        this.mo?.disconnect();
111	        if (this.registry.size === 0) {
112	            this.mo = undefined;
113	            return;
114	        }
115	        const attributeFilter = [...this.registry.values()].map((r) => r.attr);
116	        this.mo = new MutationObserver((muts) => this._handle(muts));
117	        this.mo.observe(this.engine.el, {
118	            childList: true,
119	            subtree: true,
120	            attributes: true,
121	            attributeFilter,
122	            attributeOldValue: true,
123	        });
124	    }
125	
126	    /**
127	     * 收集 root（含自身）子树下、挂有任何 runtime 指令属性的元素 → 该元素命中的指令名列表。
128	     *
129	     * querySelectorAll 无法匹配任意修饰符前缀，故遍历属性名对各 attrRe 做测试（同旧 loading 实现）。
130	     */
131	    collectEls(root: HTMLElement): Map<HTMLElement, string[]> {
132	        const out = new Map<HTMLElement, string[]>();
133	        const visit = (el: HTMLElement) => {
134	            if (this._inSlotRoot(el)) return; // slot 盲区：child engine 管辖，本 dispatcher 致盲
135	            const names = new Set<string>();
136	            for (const attrName of el.getAttributeNames()) {
137	                for (const [name, reg] of this.registry) {
138	                    if (reg.attrRe.test(attrName)) {
139	                        names.add(name);
140	                        break;
141	                    }
142	                }
143	            }
144	            if (names.size) out.set(el, [...names]);
145	        };
146	        visit(root);
147	        root.querySelectorAll("*").forEach((n) => {
148	            if (n instanceof HTMLElement) visit(n);
149	        });
150	        return out;
151	    }
152	
153	    /** 挂载实例（已存在则跳过）：实例化 → 注入 el → mounted → 广播 */
154	    mount(el: HTMLElement, name: string): void {
155	        let byEl = this.instances.get(name);
156	        if (byEl?.has(el)) return;
157	        const info = getDirectives(el).find((d) => d.name === name);
158	        if (!info) return; // 属性被识别但解析无该指令（理论不会）
159	        const entry = this.registry.get(name);
160	        if (!entry) return;
161	        const inst = new entry.Cls(this.engine, undefined, info);
162	        inst.el = el;
163	        if (!byEl) {
164	            byEl = new Map();
165	            this.instances.set(name, byEl);
166	        }
167	        byEl.set(el, inst);
168	        inst.mounted();
169	        this.engine.emit(`directive/${name}/mounted` as any, { name, el });
170	    }
171	
172	    /** 卸载实例（不存在则跳过）：unmounted → 删 → 广播 */
173	    unmount(el: HTMLElement, name: string): void {
174	        const byEl = this.instances.get(name);
175	        const inst = byEl?.get(el);
176	        if (!inst) return;
177	        byEl!.delete(el);
178	        inst.unmounted();
179	        this.engine.emit(`directive/${name}/unmounted` as any, { name, el });
180	    }
181	
182	    /** 属性值变化：attrChanged（保留实例状态如 delay 定时器）→ 广播 */
183	    private attrChange(el: HTMLElement, name: string, newVal: string, oldVal: string): void {
184	        const inst = this.instances.get(name)?.get(el);
185	        if (!inst) return;
186	        (inst as RuntimeDirective).attrChanged?.(newVal, oldVal);
187	        this.engine.emit(`directive/${name}/attr-changed` as any, { name, el, newVal, oldVal });
188	    }
189	
190	    /** observer 回调：childList 增/删 → collectEls 逐指令 mount/unmount；attributes → 三态路由 */
191	    private _handle(muts: MutationRecord[]): void {
192	        for (const mut of muts) {
193	            if (mut.type === "childList") {
194	                mut.addedNodes.forEach((n) => {
195	                    if (n instanceof HTMLElement)
196	                        for (const [el, names] of this.collectEls(n)) for (const name of names) this.mount(el, name);
197	                });
198	                mut.removedNodes.forEach((n) => {
199	                    if (n instanceof HTMLElement)
200	                        for (const [el, names] of this.collectEls(n)) for (const name of names) this.unmount(el, name);
201	                });
202	            } else if (mut.type === "attributes" && mut.attributeName) {
203	                
204	                const el = mut.target;
205	                if (!(el instanceof HTMLElement)) continue;
206	                if (this._inSlotRoot(el)) continue; // slot 盲区：属性变化交 child engine dispatcher
207	                // 定位该属性所属的 runtime 指令（attrRe 命中即止；属性名唯一归属一个指令）
208	                for (const [name, reg] of this.registry) {
209	                    if (reg.attrRe.test(mut.attributeName)) {
210	                        this._attrThreeState(el, name, reg.attr, mut.oldValue ?? "");
211	                        break;
212	                    }
213	                }
214	            }
215	        }
216	    }
217	
218	    /** 属性三态：新增属性→mount / 删除属性→unmount / 值变→attrChange（同旧 loading observer 语义） */
219	    private _attrThreeState(el: HTMLElement, name: string, attr: string, oldVal: string): void {
220	        const has = el.hasAttribute(attr);
221	        const existed = this.instances.get(name)?.has(el) ?? false;
222	        if (has && !existed) this.mount(el, name);
223	        else if (!has && existed) this.unmount(el, name);
224	        else if (has && existed) {
225	            const newVal = el.getAttribute(attr) ?? "";
226	            if (newVal !== oldVal) this.attrChange(el, name, newVal, oldVal);
227	        }
228	    }
229	
230	    /** engine.destroy 调用：断开 observer + 全实例 unmounted + 清空（不移除全局共享样式，KISS） */
231	    dispose(): void {
232	        this.mo?.disconnect();
233	        this.mo = undefined;
234	        for (const byEl of this.instances.values()) {
235	            for (const inst of byEl.values()) {
236	                try {
237	                    inst.unmounted();
238	                } catch (e: any) {
239	                    this.engine.logger.error(e);
240	                }
241	            }
242	            byEl.clear();
243	        }
244	        this.instances.clear();
245	    }
246	}
