export * from "./bind";
export * from "./bind-spread";
export * from "./data";
export * from "./form";
export * from "./field";
export * from "./on";
export * from "./for";
export * from "./html";
export * from "./model";
export * from "./switch";
export * from "./teleport";
export * from "./text";
export * from "./tree";
export * from "./if";
export * from "./else";
export * from "./case";
export * from "./show";
export * from "./loading";
export * from "./slot";
export * from "./scope";
export * from "./component";
export * from "./icon";
export * from "./icon-define";
export * from "./use";
export * from "./import";

import type { AutoSparkDirectiveBase } from "../base";
import { TextDirective } from "./text";
import { HtmlDirective } from "./html";
import { IfDirective } from "./if";
import { ElseDirective } from "./else";
import { SwitchDirective } from "./switch";
import { CaseDirective } from "./case";
import { ShowDirective } from "./show";
import { ForDirective } from "./for";
import { TreeDirective } from "./tree";
import { DataDirective } from "./data";
import { BindDirective } from "./bind";
import { OnDirective } from "./on";
import { LoadingDirective } from "./loading";
import { SlotDirective } from "./slot";
import { ModelDirective } from "./model";
import { ScopeDirective } from "./scope";
import { ComponentDirective } from "./component";
import { UseDirective } from "./use";
import { ImportDirective } from "./import";
import { FormDirective } from "./form";
import { FieldDirective } from "./field";
import { IconDirective } from "./icon";
import { IconDefineDirective } from "./icon-define";

/**
 * 预设指令映射：指令名 → 指令类。
 *
 * 显式映射，避免依赖类的 `Function.name`。注册核心闭环指令（text/html/if/show/for/data/bind/on/loading/slot）
 * + `scope`/`component`（ADR-0022：x-scope 结构占位、x-component 命名组件供体，承接 ADR-0021）
 * + `use`（ADR-0022：x-use 组件实例化指令）
 * + `import`（ADR-0022：x-import 远程组件加载指令）。
 * `x-class` / `x-style` 经 getDirectives 解析期归一化为 `bind+class` / `bind+style`，无独立指令类。
 * `x-component` 经 compiler 前置 transformer 拦截、永不被实例化，注册仅为合法可发现名位。
 * `x-else` / `x-else-if` 同为名位（分支链逻辑在 IfDirective，剪枝在 compiler 前置 transformer，ADR-0034）；
 * `x-case` / `x-default` 亦为名位（分支选择逻辑在 SwitchDirective，剪枝同走前置 transformer，ADR-0037）。
 * 
 * 注意：原 `x-patch` 指令已移除，因为 `x-scope` 指令可以完全替代其功能。
 * `x-scope` 同样是零副作用的 no-op 指令，能让纯静态元素建 scope 进入正向桥，
 * 从而被 `engine.patch` 定位。详见 ADR-0021 和 scope.ts 注释。
 */
export const presetDirectives: Record<string, typeof AutoSparkDirectiveBase> = {
    text: TextDirective,
    html: HtmlDirective,
    if: IfDirective,
    "else-if": ElseDirective,
    else: ElseDirective,
    switch: SwitchDirective,
    case: CaseDirective,
    default: CaseDirective,
    show: ShowDirective,
    for: ForDirective,
    tree: TreeDirective,
    data: DataDirective,
    bind: BindDirective,
    on: OnDirective,
    model: ModelDirective,
    loading: LoadingDirective,
    slot: SlotDirective,
    scope: ScopeDirective,
    component: ComponentDirective,
    use: UseDirective,
    import: ImportDirective,
    form: FormDirective,
    field: FieldDirective,
    icon: IconDirective,
    "icon-define": IconDefineDirective,
};

import type { Watcher } from "autostore";
import type { AutoSparkScope } from "../scope";
import type { AutoSpark } from "../engine";
import type { AutoDirectiveInfo } from "./types";

/**
 * 指令类别（DirectiveKind）
 *
 * 区分一条指令归属哪条执行通道。值为 const object + 字面量联合（自文档、可序列化、
 * 无 enum 运行时/互操作桎梏），保留 0/1/2 数值身份。
 *
 * - `Compile`(0，默认)：编译时指令，走 scope 通道。
 * - `Runtime`(1)：运行时指令，走 observer 通道。
 * - `Hybrid`(2)：混合指令，两条通道皆走。
 *
 * 详见 docs/adr/0001-directive-kind-system.md。
 */
export const DirectiveKind = {
    /** 编译时指令：编译期变换树、属性被剥除，走 scope 通道（created/compile/destroy） */
    Compile: 0,
    /** 运行时指令：编译器致盲、属性保留，走 observer 通道（mounted/unmounted/attrChanged） */
    Runtime: 1,
    /** 混合指令：scope 通道管反应性 + observer 通道管生命周期，两通道职责正交 */
    Hybrid: 2,
} as const;
export type DirectiveKind = (typeof DirectiveKind)[keyof typeof DirectiveKind];

/**
 * 运行时指令契约（observer 通道）。
 *
 * `Runtime` / `Hybrid` 指令 `extends AutoSparkDirectiveBase implements RuntimeDirective`。
 * 基类已为三个钩子提供空实现，故调用总安全；此接口仅作编译期契约/文档，运行时判别以
 * `static kind` 为准（`Runtime`/`Hybrid`）。
 */
export interface RuntimeDirective {
    /** 元素被 observer 检测到添加/挂载时调用（建立订阅、初始化） */
    mounted(): void;
    /** 元素被移除时调用（清理资源） */
    unmounted(): void;
    /** 同名属性值变化时调用（仅重绑订阅，保留实例状态如定时器；非 unmount+remount） */
    attrChanged?(newVal: string, oldVal?: string): void;
}

/**
 * 指令基类
 *
 * 所有内置/自定义指令均继承此类。指令名通过 `presetDirectives` 的 key 标识
 * （不使用类的 `static name`——它会被 `Function.name` 覆盖，无法可靠设为 "text" 等）。
 *
 * `priority` / `singleton` / `kind` 为**静态**字段：`createDirectives` 需在实例化之前据它们做
 * 优先级排序、同名单例去重、以及按 kind 分流执行通道，故必须静态可访问。子类用 `static override` 覆盖。
 *
 * ## 执行通道（按 kind 分流，见 ADR-0001）
 *
 * - **scope 通道**（Compile / Hybrid）：编译器建 scope → 实例化 → `created`/`compile`/`destroy`。
 *   `binding` 由 scope 提供，反应式来源 `scope.watch`（相对表达式 / x-data 局部变量 / x-for item）。
 * - **observer 通道**（Runtime / Hybrid）：编译器致盲（不建 scope、不过滤实例化），属性保留在结果
 *   DOM；由 `static initialize` 建立的 MutationObserver 检测 add/remove/attr-change，分别触发
 *   `mounted`/`unmounted`/`attrChanged`。Runtime 实例**无 binding**，反应式来源 `engine.store.watch`
 *   （仅绝对路径/全局表达式，无 scope 相对表达式）。Hybrid 同时具备 binding（scope 通道）与 observer 通道。
 *
 * `el` 与 `binding.el` 解耦：scope 通道实例由构造从 `binding.el` 取得；observer 通道实例由
 * `initialize` 内的工厂直接注入 `el`（无 binding）。
 *
 * ## 类级初始化钩子（所有 kind 通用，可选）
 *
 * `static initialize(engine)` / `static dispose(engine)` 在 engine 初始化/销毁时对**每个注册指令类**
 * 调用一次（不分 kind；晚注册的指令在 `DirectiveManager.set` 时补调）。基类提供 no-op 默认，
 * 指令按需 override——典型用途：runtime 指令建立 per-engine observer、注入全局样式、预编译资源等。
 */
export class AutoSparkDirectiveBase {
    /**
     * 指令类别（静态，默认 Compile）：决定走哪条执行通道。
     * 子类按需 `static override kind = DirectiveKind.Runtime | Hybrid`。
     */
    static readonly kind: DirectiveKind = DirectiveKind.Compile;
    /**
     * 处理优先级（静态）：值越大越先执行。
     * 典型顺序：x-for(100) → x-if(80) → x-bind/x-on(50) → x-text/x-html(0)。
     */
    static readonly priority: number = 0;
    /**
     * 同名单例策略（静态）：
     * - true（默认）：同名只保留最后声明的，如 `<span x-text="a" x-text="b"/>` 取 b；
     * - false：允许同名多实例，如 `x-class`。
     */
    static readonly singleton: boolean = true;
    /**
     * 是否占有子树（静态，结构指令）：返回 true 时 compiler 跳过该元素子节点的自动递归，
     * 改由指令自行编译/管理子树（如 x-for 重复、x-if 条件销毁）。
     *
     * 默认 false。结构指令按需 override；可依据 info（如修饰符）动态决定——
     * x-if 仅 eager 模式占有子树，`.keepalive`/`x-show` 不占有。
     */
    static ownsChildren(_info: AutoDirectiveInfo): boolean {
        return false;
    }

    /**
     * 类级初始化钩子（静态，可选，所有 kind 通用）。
     *
     * engine 初始化后（autostart 的 compile 之后）对每个注册指令类调用一次；晚注册的指令在
     * `DirectiveManager.set` 时补调。典型用途：runtime/hybrid 指令建立 per-engine 的
     * MutationObserver、注入全局样式、预编译类级资源。基类 no-op，按需 override。
     *
     * **幂等**：同一 (类, engine) 仅调用一次（由 DirectiveManager 的 _initialized 集合保证）。
     * **回收对称**：建立的资源须在 `dispose(engine)` 中释放。
     */
    static initialize(_engine: AutoSpark): void {}
    /**
     * 类级销毁钩子（静态，可选，所有 kind 通用）。
     *
     * `engine.destroy()` 时对每个曾 `initialize` 的指令类调用一次。职责：断开 observer、
     * 销毁全部 live 实例、释放类级资源。**不移除**文档级共享资源（如全局 `<style>`——多 engine 共用、
     * 体量可忽略，违背 KISS）。基类 no-op，按需 override。
     */
    static dispose(_engine: AutoSpark): void {}

    /** 原始指令信息（完整保留，含 name/attr 等） */
    info: AutoDirectiveInfo;
    /** 属性参数，如 @click 的 click、x-bind:title 的 title */
    attr?: string;
    modifiers?: string[];
    options?: Record<string, any>;
    value?: any;
    engine: AutoSpark;
    /**
     * 所属 scope（scope 通道实例必有；observer 通道的 Runtime 实例实际为 undefined，但永不访问）。
     * Hybrid 实例同时具备 binding（走 scope 通道）与 observer 通道。
     *
     * 类型保持非空：所有 scope 通道指令（Compile/Hybrid）始终由 compiler 提供 scope，访问 `this.binding`
     * 永远安全。Runtime 实例由 `initialize` 工厂以 `binding=undefined` 构造（见构造函数断言），但其代码路径
     * 从不访问 binding——故非空类型对实际使用恒真，避免给全部编译时指令加 `!` 断言的噪音。
     */
    binding: AutoSparkScope;
    /**
     * 宿主元素。scope 通道实例由构造从 `binding.el` 取得；Runtime 实例由 `initialize` 工厂注入。
     * 与 binding 解耦，两类通道统一通过 `this.el` 访问宿主。
     */
    el: HTMLElement;
    /** 本指令持有的 watcher（由具体指令维护；scope 通道由 scope.destroy 统一 off，Runtime 由 unmounted 自行 off） */
    watchers: Watcher[] = [];

    /**
     * @param engine   引擎实例
     * @param binding  所属 scope（Runtime 实例传 undefined，由调用方随后注入 el）
     * @param info     原始指令信息（来自 getDirectives）；value/attr/modifiers/options 同时提取为便捷字段
     */
    constructor(
        engine: AutoSpark,
        binding: AutoSparkScope | undefined,
        info: AutoDirectiveInfo,
    ) {
        this.engine = engine;
        // Runtime 实例 binding 为 undefined；断言为非空以让 scope 通道指令的 this.binding 访问类型安全
        // （Runtime 代码路径从不访问 binding，不变量恒真）。
        this.binding = binding as AutoSparkScope;
        this.info = info;
        this.value = info.value;
        this.attr = info.attr;
        this.modifiers = info.modifiers;
        this.options = info.options;
        // scope 通道：从 binding 取 el；Runtime 实例 binding 为 undefined → el 暂为 undefined，由 initialize 工厂注入
        this.el = binding?.el as HTMLElement;
    }

    get template() {
        return this.binding?.template;
    }

    /**
     * 读取指令配置（两层 fallback，ADR-0007）。
     *
     * 查询顺序：指令选项（`this.options`，含解析期注入的 modifier 开关）→ 宿主选项
     * （`this.binding.hostOptions`，即 `x-options`）。显式写值（含 `false`）即命中、阻断回退；
     * 两层均无返回 undefined。
     *
     * modifier 与指令选项经此方法等价：`.global` 与 `x-{name}-options="{global:true}"` 统一可读。
     * Runtime 指令（无 binding）仅查指令选项（无宿主选项回退）。
     */
    getOption(key: string): any {
        if (this.options && Object.prototype.hasOwnProperty.call(this.options, key)) {
            return this.options[key];
        }
        const host = this.binding?.hostOptions;
        if (host && Object.prototype.hasOwnProperty.call(host, key)) {
            return host[key];
        }
        return undefined;
    }

    /** 指令级 warn 快捷方法（DRY：避免每处写 this.engine.logger.warn） */
    protected warn(msg: string): void {
        this.engine.logger.warn(msg);
    }

    /** 指令级 error 快捷方法（DRY：避免每处写 this.engine.logger.error） */
    protected error(msg: string): void {
        this.engine.logger.error(msg);
    }

    // ── scope 通道钩子（Compile / Hybrid）──────────────────────────────
    /** 初始化：建立订阅（watch）的时机 */
    created() {}
    /** 元素插入 DOM 后调用 */
    mounted() {}
    unmounted() {}

    /**
     * 编译期首次渲染。
     *
     * @param context 响应式根状态（engine.state = store.state）
     * @param parent  父元素
     * @returns HTMLElement 表示内部还有模板需上层递归；undefined/void 表示无需
     */
    compile(
        _context: Record<string, any>,
        _parent: HTMLElement,
    ): HTMLElement | undefined | void {}

    /**
     * 销毁钩子（scope 通道）：元素移除或 scope 销毁时调用，用于清理自定义资源。
     * 默认空实现，子类按需覆盖。Runtime 指令改用 `unmounted`。
     */
    destroy(_el: HTMLElement): void {}
}

import type { AutoSparkScope } from "../scope";
import type { StyleBind } from "../utils/styleBind";

/**
 * 组件定义的生命周期钩子集合（ADR-0022 决策三）。
 *
 * 四阶段钩子，实例化时从 `<script setup>` 求值结果中按名收集为数组，串行调用（try-catch 容错，
 * 单个失败不影响其余）。挂到实例 scope 的 `hooks` 字段，由 compileChild 实例化流程在对应阶段触发。
 *
 * **砍掉的钩子**（与本引擎架构不契合）：
 * - `activated`/`deactivated`：引擎无组件实例缓存层（scope 销毁即销毁），无自然触发点。
 * - `beforeUpdate`/`updated`：细粒度响应式无"组件整体重渲染"节点。
 */
export type ComponentHookPhase = "created" | "mounted" | "beforeUnmount" | "unmounted";

/**
 * 组件实例 methods 执行时的 this 上下文（ADR-0022 决策二-3）。
 *
 * 复用 `AutoSparkActionContext` 形态——`data` 是 `scope.getContext()` 聚合视图（含组件 data 域，
 * 响应式、可读可写），`state` 是 `engine.store.state`。组件 methods 注入 `scope.actions` 后，
 * 由 x-on 的 action 求值器（`on/eval.ts`）构造此上下文并 `action.call(ctx, ...)` 调用。
 *
 * 本接口与 `AutoSparkActionContext` 字段一致，单独声明以表达"组件 methods 的 this"语义。
 */
export interface ComponentMethodContext {
    /** 触发元素（x-on 的目标元素，组件内任意指令元素） */
    el: HTMLElement;
    /** 原生事件（仅 x-on 场景有值） */
    $event?: Event;
    /** 组件聚合数据视图（localData + data(x-use 传入 + data() 返回) + 全局 state），响应式、可写 */
    data: Record<string, any>;
    /** 当前 scope */
    scope: AutoSparkScope;
    [key: string]: any;
}

/**
 * `<script setup>` 对象字面量求值后的标准形态（ADR-0022 决策四-1/2）。
 *
 * 由 `new Function('return ' + scriptText)()` 求值得到。多个 `<script setup>` 按段分类合并
 * （`data` 收集所有函数、实例化时依次调用合并返回值；`methods` 浅合并；同名 hooks 串行）。
 *
 * - `data`：返回组件初始状态的函数（注入 scope.data 响应式域，**先于** x-use 传入值，后者覆盖）。
 * - `methods`：组件方法对象，注入 `scope.actions`（复用 x-on action 查找，this=ComponentMethodContext）。
 * - `created`/`mounted`/`beforeUnmount`/`unmounted`：四阶段生命周期钩子函数。
 */
export interface ComponentSetup {
    data?: () => Record<string, any>;
    methods?: Record<string, (...args: any[]) => any>;
    /**
     * 组件实例的非响应式局部变量（ADR-0022 决策二-3 (10)）。
     *
     * 注入 `scope._locals`（普通对象、**不进聚合视图**）——模板表达式 `{{x}}` 读不到，仅经 Proxy this
     * 的 `this.<key>` 访问（method/data/framework key 优先级高于 _locals）。典型用途：定时器句柄、
     * 缓存、防抖标记等实例内部状态。多 `<script setup>` 的 locals **浅合并**。
     */
    locals?: Record<string, any>;
    created?: () => void;
    mounted?: () => void;
    beforeUnmount?: () => void;
    unmounted?: () => void;
}

/**
 * 合并后的组件钩子表：每阶段一个函数数组（多个 `<script setup>` 同名 hook 串行）。
 */
export type ComponentHooks = Record<ComponentHookPhase, Array<() => void>>;

/**
 * 组件定义（ADR-0022 决策二-1）。
 *
 * compiler 前置 transformer 命中 x-component 元素时，提取其 `<script setup>` / `<style>` 子节点、
 * 求值合并 setup、深克隆剩余 DOM 为冻结快照，组装成本对象。
 *
 * `getComponent(name)` 返回 HTMLElement 快照（保持 x-loading 等消费者契约不变）；ComponentDef 的额外
 * 元数据（setup/hooks/styles）经 engine 的 `_componentDefs`（WeakMap，以快照根为 key）反查，供 x-use
 * 实例化时取用。
 *
 * **嵌套私有子组件无需定义链**：x-use 实例化父组件 A 时 `compileSubtree` 编译 A 快照子树，内层
 * `x-component="B"` 经 transformElement 再次命中收集器，B 归属到 **A 的实例 scope**
 * （`A实例scope.components`）——运行期 scope 链天然实现严格私有（U5=A），不需定义 scope 链。
 */
export interface ComponentDef {
    /** 组件名（无值 x-component 取 "default"） */
    name: string;
    /** 冻结快照根元素（深克隆、保留指令属性、**已移除** `<script setup>`/`<style>` 子节点、未编译） */
    snapshot: HTMLElement;
    /** 合并后的 setup（data 方法、methods）；无 `<script setup>` 时为 undefined */
    setup: ComponentSetup | undefined;
    /** 合并后的钩子表（从 setup 提取，实例化时克隆到 scope.hooks）；无钩子时为 undefined */
    hooks: ComponentHooks | undefined;
    /** 合并后的组件作用域 CSS 文本数组（每个 `<style>` 一项，**已提取 bind** 后的改写文本）；无 `<style>` 时为 undefined */
    styles: string[] | undefined;
    /**
     * 响应式 `<style>` bind 清单（ADR-0022 决策四-4.1）。
     *
     * 编译期 `extractStyleBinds` 从 `<style>` 声明值的 `bind(expr)` 提取、跨块按 expr 全局去重，
     * 派生 CSS 变量名（纯路径 → `--{路径}`，表达式 → `--h{hash}`）。声明性清单，多实例共享只读、无实例状态。
     * 实例化期（`instantiateComponent`）遍历此清单调 `hostScope.watch(expr)`，求值结果写入组件根元素的
     * CSS 变量（每实例独立）；null/undefined 不写、走 `var(--name, unset)` 回退。无 bind 时为 undefined。
     */
    styleBinds: StyleBind[] | undefined;
}

