1	/**
2	 * 模板编译器
3	 *
4	 * 基于 transformElement 深度优先重建模板树：对每个含指令的元素，浅克隆（保留
5	 * 普通属性）、移除指令属性、创建 AutoSparkScope 并执行其指令生命周期。
6	 *
7	 * **浅克隆是安全的**：transformElement 命中 transformer 后会用返回的新元素替换原节点，
8	 * 并继续递归**原节点的子节点**挂到新元素下——因此子树会被完整重建（等价深克隆，
9	 * 但允许每个子节点各自走 transformer 处理）。
10	 *
11	 * 编译期通过 templateScopeMap 建立 scope 父子关系（向上查找最近指令祖先），
12	 * 并让子作用域继承父的 localData（供 x-for 注入的 item/index 向下传递到嵌套子元素）。
13	 */
14	import { AutoSparkScope } from "../scope";
15	import { SCOPES_KEY } from "../engine";
16	import { removeDirectives } from "../directives/utils/removeDirectives";
17	import { isDirectiveAttr } from "../directives/utils/isDirectiveAttr";
18	import { DirectiveKind } from "../directives/base";
19	import { ModelDirective } from "../directives/presets/model";
20	import type { AutoDirectiveInfo } from "../directives/types";
21	import type { AutoSpark } from "../engine";
22	import {
23	    transformElement,
24	    type NodeTransformer,
25	    type OwnsChildrenResult,
26	} from "../utils/transformElement";
27	import { hasDirectives } from "../directives/utils/hasDirectives";
28	import { hasMustache, isRawTextElement, parseInterpolation, synthAttrExpr } from "./mustache";
29	import { collectDataScripts, isDataScript, type DataScriptStash } from "./dataScript";
30	import {
31	    getDirectiveAttrValue,
32	    isAsyncDataValue,
33	    isAsyncHtmlValue,
34	} from "../directives/presets/async-source";
35	import { buildComponentDef } from "./collect";
36	import type { ComponentDef } from "../directives/component-def";
37	import { mountComponentScopedAttr, injectComponentStyle } from "../utils/scopedStyle";
38	import { coerceStyleValue, type StyleBind } from "../utils/styleBind";
39	import { iconRegistry } from "../icons/registry";
40	
41	/**
42	 * 元素是否含插值（需建 scope 的判据之一）。
43	 *
44	 * 探测两处 `{{`：**直接文本子节点**（文本插值）与**自身非指令属性值**（属性插值）。
45	 * 均非递归、O(直接子节点/属性数)，绝不退化成 O(n²)。raw-text 元素（SCRIPT/STYLE）
46	 * 一律不插值（见 ADR-0004 决策 7）。
47	 */
48	function hasInterpolation(el: HTMLElement): boolean {
49	    if (isRawTextElement(el)) return false;
50	    for (let i = 0; i < el.childNodes.length; i++) {
51	        const child = el.childNodes[i];
52	        if (child && child.nodeType === Node.TEXT_NODE && hasMustache(child.nodeValue)) return true;
53	    }
54	    for (let i = 0; i < el.attributes.length; i++) {
55	        const attr = el.attributes[i];
56	        if (attr && !isDirectiveAttr(attr.name) && hasMustache(attr.value)) return true;
57	    }
58	    return false;
59	}
60	
61	/**
62	 * 元素是否声明某指令属性（含修饰符形态）。
63	 *
64	 * `hasAttribute("x-if")` 对 `x-if.keepalive`（属性名含修饰符后缀）为 false，孤儿分支
65	 * 判据若用精确匹配会把 keepalive 宿主的分支误报孤儿——本 helper 匹配 `x-if` 与
66	 * `x-if.<modifiers>` 两种形态（ADR-0034 keepalive 误 warn 的修复，ADR-0037 同构沿用）。
67	 */
68	function hasDirectiveAttr(el: HTMLElement, name: string): boolean {
69	    for (let i = 0; i < el.attributes.length; i++) {
70	        const attrName = el.attributes[i]!.name;
71	        if (attrName === name || attrName.startsWith(`${name}.`)) return true;
72	    }
73	    return false;
74	}
75	
76	export class AutoSparkCompiler {
77	    readonly engine: AutoSpark;
78	    /** 编译期：原树模板元素 → scope 映射，用于建立 scope 父子关系与 localData 继承 */
79	    private templateScopeMap = new WeakMap<HTMLElement, AutoSparkScope>();
80	    /**
81	     * 编译期：scope → 数据脚本预扫产物（ADR-0032）。compileElement 在 scope.compile() 前
82	     * 写入，DataDirective.created()（优先级 200，compile 内最先执行）一次性消费后删除——
83	     * 每实例编译各写各的，无跨实例共享。
84	     */
85	    private dataScriptStash = new WeakMap<AutoSparkScope, DataScriptStash>();
86	
87	    constructor(engine: AutoSpark<any>) {
88	        this.engine = engine;
89	    }
90	
91	    private _getTransformers(): NodeTransformer<HTMLElement>[] {
92	        return [
93	            // 前置：<script type="autospark/actions"> 提取为局部 action 后剪枝（普通 script 原样保留）。
94	            // 提取/解析/注入收编于 ActionManager；scope 解析留在 compiler（依赖私有 templateScopeMap）
95	            [
96	                (node: Node) => node instanceof HTMLScriptElement && node.type === "autospark/actions",
97	                (script: HTMLElement) =>
98	                    this.engine.actionsManager.extractScript(
99	                        script as HTMLScriptElement,
100	                        this._findNearestScope(script as HTMLScriptElement),
101	                    ),
102	            ],
103	            // 前置：旧写法 <script type="actions">（ADR-0031 更名前）——warn 提示迁移 + 剪枝不执行
104	            [
105	                (node: Node) => node instanceof HTMLScriptElement && node.type === "actions",
106	                () => {
107	                    this.engine.logger.warn(
108	                        `<script type="actions"> 已更名为 <script type="autospark/actions">（ADR-0031），该脚本未注册`,
109	                    );
110	                    return null;
111	                },
112	            ],
113	            // 前置：<script type="autospark/data"> ——内容已在父元素编译期预扫消费
114	            //（compileElement 调 collectDataScripts，ADR-0032），此处仅剪枝（不进渲染 DOM）
115	            [
116	                (node: Node) => isDataScript(node),
117	                () => null,
118	            ],
119	            // 前置：x-fallback 特例子节点（ADR-0033 决策 4 / ADR-0035 决策 3-4）——直接父元素为
120	            // 异步源宿主（异步 x-data，或异步 x-html 且宿主无双异步 x-data——双异步时 fallback
121	            // 归 x-data 独占）时已被物种指令采集（collectFallback），剪枝不进渲染 DOM；
122	            // 孤立 x-fallback（父无异步源）→ warn + 当普通元素放行（默认浅克隆继续编译）。
123	            // 指令属性值读取兼容修饰符变体（x-data.global / x-html.compile，getDirectiveAttrValue）
124	            [
125	                (node: Node) => node instanceof HTMLElement && node.hasAttribute("x-fallback"),
126	                (el: HTMLElement) => {
127	                    const parent = el.parentElement;
128	                    if (parent) {
129	                        const dataVal = getDirectiveAttrValue(parent, "x-data");
130	                        // x-data 侧认领（ADR-0033）；双异步时 x-data 优先独占（ADR-0035 决策 6）
131	                        if (dataVal !== null && isAsyncDataValue(dataVal)) return null;
132	                        // x-html 侧认领（ADR-0035）：仅宿主无异步 x-data 时（fallback 归属唯一）
133	                        const htmlVal = getDirectiveAttrValue(parent, "x-html");
134	                        if (htmlVal !== null && isAsyncHtmlValue(htmlVal)) return null;
135	                    }
136	                    this.engine.logger.warn(
137	                        `x-fallback: 父元素未声明异步源（异步 x-data / 异步 x-html），按普通元素渲染（ADR-0033/0035）`,
138	                    );
139	                    return el.cloneNode(false) as HTMLElement;
140	                },
141	            ],
142	            // 前置：x-else-if / x-else 条件分支（ADR-0034）——分支快照由 IfDirective 在宿主 created 期
143	            // 主动扫描直接子元素克隆收集（模板只读），本层仅负责**剪枝**：分支是备选模板、
144	            // 永不进结果 DOM（eager 的 compileSubtree 与 keepalive 的主 walk 两条子树编译通道统一拦截）。
145	            // 父元素无 x-if 指令属性（含修饰符形态）→ 孤儿分支：warn + 丢弃（同 x-component 孤儿惯例）
146	            [
147	                (node: Node) =>
148	                    node instanceof HTMLElement &&
149	                    (node.hasAttribute("x-else-if") || node.hasAttribute("x-else")),
150	                (el: HTMLElement) => {
151	                    const parent = el.parentElement;
152	                    if (!(parent && hasDirectiveAttr(parent, "x-if"))) {
153	                        this.engine.logger.warn(
154	                            `x-else-if/x-else: 父元素未声明 x-if，分支被丢弃。分支必须是 x-if 宿主的直接子元素（ADR-0034）`,
155	                        );
156	                    }
157	                    return null;
158	                },
159	            ],
160	            // 前置：x-case / x-default 分支选择（ADR-0037）——与 x-else-if/x-else 同构：快照由
161	            // SwitchDirective 在宿主 created 期克隆收集，本层仅负责剪枝（两条子树编译通道统一拦截）。
162	            // 父元素无 x-switch 指令属性（含修饰符形态）→ 孤儿分支：warn + 丢弃（含误写在 x-if 宿主内的 x-case）
163	            [
164	                (node: Node) =>
165	                    node instanceof HTMLElement &&
166	                    (node.hasAttribute("x-case") || node.hasAttribute("x-default")),
167	                (el: HTMLElement) => {
168	                    const parent = el.parentElement;
169	                    if (!(parent && hasDirectiveAttr(parent, "x-switch"))) {
170	                        this.engine.logger.warn(
171	                            `x-case/x-default: 父元素未声明 x-switch，分支被丢弃。分支必须是 x-switch 宿主的直接子元素（ADR-0037）`,
172	                        );
173	                    }
174	                    return null;
175	                },
176	            ],
177	            // 前置：x-component 命名组件——收集冻结快照到最近祖先 scope.components 后剪枝（不进结果 DOM）。
178	            // 须排在 HTMLElement 通用规则（compileElement）之前，first-match-wins 命中后不再走通用编译，
179	            // 故 x-component 元素不建 scope、不实例化其上其他指令（同元素 x-text 等随组件冻结，ADR-0022）。
180	            [
181	                (node: Node) => node instanceof HTMLElement && node.hasAttribute("x-component"),
182	                (componentEl: HTMLElement) => this._collectComponent(componentEl),
183	            ],
184	            // 前置：x-icon-define 图标定义（ADR-0046）——声明性资源：取首个 <svg> 子元素上交全局
185	            // 图标注册表（AutoSpark.icons）后剪枝（不进结果 DOM）。指令类仅为名位（x-component 同构），
186	            // 永不被实例化。动态区域（x-for 项模板 / x-html.compile / 组件快照）内重复定义幂等覆盖。
187	            [
188	                (node: Node) => node instanceof HTMLElement && node.hasAttribute("x-icon-define"),
189	                (iconEl: HTMLElement) => this._collectIconDefine(iconEl),
190	            ],
191	            // 文本节点插值：含 {{}} 的文本节点拆分 + 注册。scope 经父元素查 templateScopeMap
192	            // （父元素在自身 walk 前已建 scope，含插值的 directive-less 元素亦由 hasInterpolation
193	            // 触发建 scope）。无 scope（raw-text 父等）则原样克隆。见 ADR-0004 决策 1/4。
194	            [
195	                (node: Node) =>
196	                    node.nodeType === Node.TEXT_NODE && hasMustache((node as Text).nodeValue),
197	                (node: Node) => {
198	                    const parent = node.parentElement;
199	                    const scope = parent ? this.templateScopeMap.get(parent) : undefined;
200	                    if (!scope) return node.cloneNode(true);
201	                    return this.compileTextNode(node as Text, scope);
202	                },
203	            ],
204	            [
205	                (node: Node) => node instanceof HTMLElement,
206	                (current: HTMLElement) => this.compileElement(current),
207	            ],
208	        ];
209	    }
210	
211	    /**
212	     * 收集 x-component 命名组件（ADR-0022，承接 ADR-0021）。
213	     *
214	     * 编译期前置 transformer 命中 x-component 元素时调用：把该元素**深克隆**为冻结快照，
215	     * 按名存入**最近祖先 scope** 的 `components`，然后返回 `null` 剪枝——组件元素及其子树
216	     * **不进结果 DOM、不建 scope、不实例化指令**。
217	     *
218	     * 消费者（x-loading/x-empty/x-error…）经 `scope.getComponent(name)` 沿 parent 链就近取用本快照
219	     * （到顶兜底全局组件），clone 后编译渲染、替换其默认 UI（组件兜底）。详见 ADR-0022。
220	     *
221	     * **default 唯一性已放宽**（ADR-0022 决策四-4）：同名组件直接归属同一 scope 时 warn + 后者覆盖
222	     * （不再抛错）。沿 parent 链的就近覆盖由 getComponent 就近原则处理。
223	     *
224	     * > 注：`<script setup>` / `<style>` 的提取与求值、嵌套私有子组件（定义 scope 链）在后续阶段实现，
225	     * > 当前阶段（命名硬切）保持组件行为与原 x-block 一致。
226	     *
227	     * @param componentEl 原树中的 x-component 元素（只读编译输入，仅读取其属性与结构）
228	     * @returns 固定 `null`（剪枝，x-component 永不进结果 DOM）
229	     */
230	    private _collectComponent(componentEl: HTMLElement): null {
231	        const name = (componentEl.getAttribute("x-component") ?? "").trim() || "default";
232	        // 沿原树向上找最近祖先 scope（与 _linkParent 同构：跨中间无 scope 的纯 div）。
233	        // walk 是 DFS，祖先元素已先 transform，若建了 scope 必已 templateScopeMap.set。
234	        // 注：实例化父组件时 compileSubtree 编译其快照子树，内层 x-component 经 transformElement
235	        // 再次命中本收集器，归属到父组件的**实例 scope**——运行期 scope 链天然实现嵌套私有子组件。
236	        let owner: AutoSparkScope | undefined;
237	        let p: HTMLElement | null = componentEl.parentElement;
238	        while (p) {
239	            owner = this.templateScopeMap.get(p);
240	            if (owner) break;
241	            p = p.parentElement;
242	        }
243	        if (!owner) {
244	            // 无归属：编译期 warn + 丢弃（不进 components、不进 DOM）。与引擎静默处理冗余/异常属性的风格一致。
245	            this.engine.logger.warn(
246	                `x-component: 组件 "${name}" 未找到任何祖先 scope，无法归属。请在祖先元素上声明 x-scope（或任意指令）使其建 scope。`,
247	            );
248	            return null;
249	        }
250	        // default 唯一性放宽（ADR-0022 决策四-4）：同名组件直接归属本 scope → warn + 后者覆盖（不再抛错）。
251	        // 沿 parent 链的就近覆盖由 getComponent 就近原则处理（不在此校验）。
252	        if (
253	            owner.components &&
254	            Object.prototype.hasOwnProperty.call(owner.components, name)
255	        ) {
256	            this.engine.logger.warn(
257	                `[x-component] 组件 "${name}" 在同一 scope 下重复声明，后者覆盖前者（ADR-0022 决策四-4 放宽 default 唯一性）。`,
258	            );
259	        }
260	        // 组装组件定义：提取 <script setup>/<style>、求值合并 setup、深克隆冻结快照（已剥离 script/style）。
261	        const def = buildComponentDef(componentEl, name, (msg) => this.engine.logger.warn(msg));
262	        // scope.components 仍存 HTMLElement 快照（保持 getComponent 的 HTMLElement 契约，x-loading 等消费者不变）；
263	        // ComponentDef 元数据（setup/hooks/styles）以快照根为 key 注册到 engine，供 x-use 实例化时反查。
264	        this.engine.registerComponentDef(def);
265	        if (!owner.components) owner.components = {};
266	        owner.components[name] = def.snapshot;
267	        return null;
