285	        const root: ParentNode =
286	            iconEl instanceof HTMLTemplateElement ? iconEl.content : iconEl;
287	        let svg: Element | null = null;
288	        let extraRoots = 0;
289	        for (const child of root.children) {
290	            if (child.tagName.toLowerCase() === "svg") {
291	                if (!svg) svg = child;
292	            } else {
293	                extraRoots++;
