295	        }
296	        if (!name) {
297	            this.engine.logger.warn(`x-icon-define: 缺少图标名（值留空），定义被跳过（ADR-0046）`);
298	            return null;
299	        }
300	        if (!svg) {
301	            this.engine.logger.warn(
302	                `x-icon-define: 图标 "${name}" 未找到 <svg> 子元素，定义被跳过（ADR-0046）`,
303	            );
304	            return null;
305	        }
306	        if (extraRoots > 0) {
307	            this.engine.logger.warn(
308	                `x-icon-define: 图标 "${name}" 的声明含 ${extraRoots} 个 svg 之外的根节点，已忽略（ADR-0046）`,
309	            );
310	        }
