315	    /**
316	     * 编译含 `{{}}` 的文本节点（文本插值，ADR-0004 决策 1/3）。
317	     *
318	     * 拆为「字面量段 + 表达式段」，每表达式段一个 text node + 一个 `scope.watch`；
319	     * 返回由段 text node 组成的 `DocumentFragment`（调用方 appendChild 搬入父）。
320	     *
321	     * **x-text / 非 compile 的 x-html 在场 → 返回 null（剪枝）**：x-text 整体覆写 textContent，
322	     * 若插值已建段 text node + watcher，首次 compile 后段 node 被清空成游离节点、watcher 仍订阅 →
323	     * 孤儿 watcher 泄漏。故编译期剪枝该文本节点（非「建了让 x-text 覆盖」）。见 ADR-0004 决策 5。
324	     *
325	     * **x-html.compile 例外（ADR-0017）**：compile 模式把注入内容作为子模板编译，其顶层文本插值
326	     * 应正常编译（由 recompileSubtree 注入），故 compile 模式的 html 指令不触发剪枝——宿主原生
327	     * 子节点反正被注入内容覆盖，无孤儿 watcher 风险。
328	     *
329	     * @returns DocumentFragment（段 text node 集合）；x-text / 非 compile 的 x-html 在场返回 null（剪枝）
330	     */
331	    private compileTextNode(node: Text, scope: AutoSparkScope): DocumentFragment | null {
332	        if (
333	            scope.directives.some(
334	                (d) =>
335	                    d.info.name === "text" || (d.info.name === "html" && !d.info.options?.compile),
336	            )
337	        ) {
338	            return null;
339	        }
340	        const segments = parseInterpolation(node.nodeValue ?? "");
341	        const frag = document.createDocumentFragment();
342	        if (!segments) {
343	            // 无 {{}}（filter 已筛，兜底）：原样克隆
344	            frag.appendChild(node.cloneNode(true));
345	            return frag;
346	        }
347	        for (const seg of segments) {
348	            if ("literal" in seg) {
349	                frag.appendChild(document.createTextNode(seg.literal));
350	            } else {
351	                const segNode = document.createTextNode("");
352	                const initial = scope.watch(seg.expr, ({ value }) => {
353	                    segNode.nodeValue = value == null ? "" : String(value);
354	                });
355	                segNode.nodeValue = initial == null ? "" : String(initial);
356	                frag.appendChild(segNode);
357	            }
358	        }
359	        return frag;
360	    }
