362	    /**
363	     * 属性插值 desugar（ADR-0004 决策 9-12）。
364	     *
365	     * 扫描 `el` 的非指令属性，对值含 `{{}}` 者：① 同属性已有显式 bind → 抛错（互斥）；
366	     * ② `removeAttribute` 移除原生平属性（防字面 `{{}}` 泄漏 DOM）；③ 合成表达式；
367	     * ④ 实例化 `BindDirective` 复用其五路 patch 分派（class diff / style / property /
368	     * boolean / 普通）。watcher 经 `scope.watch` 自动入 `scope.watchers`/`_updates`，
369	     * destroy/refresh 自动，无需手动登记。
370	     */
371	    private _compileAttrInterpolation(el: HTMLElement, scope: AutoSparkScope): void {
372	        const targets: Array<{ name: string; value: string }> = [];
373	        for (let i = 0; i < el.attributes.length; i++) {
374	            const attr = el.attributes[i];
375	            if (attr && !isDirectiveAttr(attr.name) && hasMustache(attr.value)) {
376	                targets.push({ name: attr.name, value: attr.value });
377	            }
378	        }
379	        for (const { name, value } of targets) {
380	            // 冲突检测：同属性已有显式 bind（:name / x-bind:name / x-class 等）
381	            const conflict = scope.directives.some(
382	                (d) => d.info.name === "bind" && d.info.attr === name,
383	            );
384	            if (conflict) {
385	                throw new Error(
386	                    `[插值冲突] 属性 "${name}" 已有显式绑定（:${name}/x-bind:${name}），与插值 ${name}="${value}" 互斥。\n` +
387	                        `请二选一：用插值 ${name}="${value}"，或显式 :${name}="<expr>"。`,
388	                );
389	            }
390	            const synthExpr = synthAttrExpr(value);
391	            el.removeAttribute(name);
392	            const BindCls = this.engine.directives.get("bind");
393	            if (!BindCls) {
394	                this.engine.logger.warn(`属性插值：未注册 bind 指令，跳过 ${name}="${value}"`);
395	                continue;
396	            }
397	            const info: AutoDirectiveInfo = { name: "bind", attr: name, value: synthExpr };
398	            const bind = new BindCls(this.engine, scope, info);
399	            bind.created();
400	        }
401	    }
