416	    /**
417	     * 沿 parentElement 向上查找最近的已注册 scope（templateScopeMap）。
418	     * 与 `_linkParent` 查找逻辑一致，用于把 script action 挂到最近祖先作用域
419	     * （查好后作为入参传给 actionsManager.extractScript，见 _getTransformers）。
420	     */
421	    private _findNearestScope(el: HTMLElement): AutoSparkScope | undefined {
422	        let p: HTMLElement | null = el.parentElement;
423	        while (p) {
424	            const scope = this.templateScopeMap.get(p);
425	            if (scope) return scope;
426	            p = p.parentElement;
427	        }
428	        return undefined;
429	    }
