451	    /**
452	     * 单条指令是否占有子树（ownsChildren）的纯判定谓词。
453	     *
454	     * 查指令类的静态 `ownsChildren(info)`。提取为谓词后，`scopeOwnsChildren`（boolean 查询）
455	     * 与 `_resolveOwnership`（需计数以检测多 owner 冲突）共用同一真相源。
456	     */
457	    private _ownsChildrenDirective(d: { info: AutoDirectiveInfo }): boolean {
458	        const cls = this.engine.directives.get(d.info.name);
459	        return !!cls?.ownsChildren?.(d.info);
460	    }
