473	    /**
474	     * 编译单个模板元素（transformElement 回调）。
475	     *
476	     * - 无指令：原样返回，transformElement 会默认浅克隆并递归子节点；
477	     * - 有指令：浅克隆 + 移除指令属性 + 建 scope + 建立 parent 关系 + 继承 localData + 执行指令。
478	     * - 含结构指令（ownsChildren，如 x-for / eager x-if）：返回 `ownsChildren` 信号，
479	     *   让 transformElement 跳过该元素子节点的自动递归——子节点由指令自行编译，
480	     *   避免"正常通道编译一次 + 指令克隆再编译"的双重冲突。
481	     *
482	     * 同元素出现多个结构指令（如 `x-for` + eager `x-if`）会在 `_resolveOwnership` 中抛错。
483	     */
484	    compileElement(template: HTMLElement): HTMLElement | OwnsChildrenResult {
485	        // 数据脚本预扫（ADR-0032）：直接子级 <script type="autospark/data"> 先于指令求值
486	        // 收集合成，与 x-data 合成单一数据对象走既有注入管道（desugar：位置无关）
487	        const dataStash = collectDataScripts(this.engine, template);
488	        // 含插值（文本/属性）但无指令的元素也需建 scope（隐式指令，ADR-0004 决策 2）；
489	        // 含数据脚本亦同——父元素等效持有 x-data（即便无任何指令属性，脚本独立成立）
490	        if (!hasDirectives(template) && !hasInterpolation(template) && !dataStash) {
491	            // 必须浅克隆：transformElement 用 live NodeList 遍历原节点子节点并挂到返回的新节点下，
492	            // 若返回原节点，appendChild 会写回原节点自身、其 childNodes 持续增长，导致 live 遍历无限循环。
493	            return template.cloneNode(false) as HTMLElement;
494	        }
495	        const el = template.cloneNode(false) as HTMLElement;
496	        removeDirectives(el, "x-", this._runtimeKeepAttr());
497	        const scope = new AutoSparkScope(this.engine, el, template);
498	        this._linkParent(template, scope);
499	        this.templateScopeMap.set(template, scope);
500	        this.engine.scopes.set(new WeakRef(el), scope);
501	        // 冲突检测先于 compile：让 x-for + eager x-if 同元素在跑任何指令生命周期前即失败
502	        const ownsChildren = this._resolveOwnership(scope);
503	        if (dataStash) {
504	            if (ownsChildren) {
505	                // 结构指令宿主的直接子级是项模板材料（ownsChildren），数据脚本无处挂载——
506	                // warn 放弃（脚本稍后仍被剪枝 transformer 移出渲染 DOM，不泄漏）
507	                this.engine.logger.warn(
508	                    `<script type="autospark/data"> 不能直接声明在结构指令（x-for/eager x-if/x-slot）宿主的直接子级（其子节点是项模板）。请移入项模板内目标元素的直接子级（ADR-0032 决策 7）。`,
509	                );
510	            } else {
511	                this._applyDataScriptStash(scope, dataStash);
512	            }
513	        }
514	        scope.compile();
515	        // 属性插值 desugar（compile 后；合成 bind 独立注册，复用 BindDirective 五路分派）
516	        this._compileAttrInterpolation(el, scope);
517	        // x-model 元数据自动注入（ADR-0020）：含 x-model 的元素从 schema 合成隐式 @ 绑定
518	        this._synthesizeModelSchemaBindings(el, scope);
519	        // 结构指令占有子树：返回 ownsChildren 信号，跳过子节点自动递归（由指令自行编译）。
520	        if (ownsChildren) {
521	            return { node: el, ownsChildren: true };
522	        }
523	        return el;
524	    }
