526	    /**
527	     * 把数据脚本预扫产物交给 scope 的 DataDirective 消费（ADR-0032 决策 4）。
528	     *
529	     * 元素已有 x-data → stash 挂 WeakMap，由 DataDirective.created()（scope.compile 内
530	     * 按优先级最先执行）消费合并；无 x-data → 合成空值 DataDirective 入列——「脚本独立成立」
531	     * 等效 x-data。入列后按类静态 priority 重排（data=200 恒最先，保证先于兄弟指令注入，
532	     * 首渲即可读到数据；重排兼容未来更高优先级的自定义指令）。
533	     */
534	    private _applyDataScriptStash(scope: AutoSparkScope, stash: DataScriptStash): void {
535	        if (!scope.directives.some((d) => d.info.name === "data")) {
536	            const DataCls = this.engine.directives.get("data");
537	            if (!DataCls) {
538	                this.engine.logger.warn(`数据脚本：未注册 data 指令，已忽略`);
539	                return;
540	            }
541	            scope.directives.unshift(new DataCls(this.engine, scope, { name: "data" }));
542	            const priority = (d: { info: AutoDirectiveInfo }) =>
543	                this.engine.directives.get(d.info.name)?.priority ?? 0;
544	            scope.directives.sort((a, b) => priority(b) - priority(a));
545	        }
546	        this.dataScriptStash.set(scope, stash);
547	    }
