595	                names.push(name);
596	            }
597	        }
598	        return (attrName: string) =>
599	            names.some(
600	                (n) =>
601	                    attrName === `x-${n}` ||
602	                    attrName.startsWith(`x-${n}.`) ||
603	                    attrName.startsWith(`x-${n}-options`),
