625	    private compileOneChild(child: Node, scope: AutoSparkScope | null): Node | null {
626	        if (child instanceof HTMLElement) {
627	            // 分支标记（x-else-if/x-else 条件链、x-case/x-default 分支选择）：剪枝（与前置
628	            // transformer 语义一致；孤儿检测的 warn 在主 walk 路径的 transformer 层发出，此处静默跳过）
629	            if (
630	                child.hasAttribute("x-else-if") ||
631	                child.hasAttribute("x-else") ||
632	                child.hasAttribute("x-case") ||
633	                child.hasAttribute("x-default")
634	            ) {
635	                return null;
636	            }
637	            return transformElement(child, this._getTransformers());
638	        }
639	        if (child.nodeType === Node.TEXT_NODE && hasMustache((child as Text).nodeValue)) {
640	            // 顶层文本插值需 scope 注册 watcher；无 scope（patch 替换到无祖先 scope 的根级）则原样克隆
641	            return scope ? this.compileTextNode(child as Text, scope) : child.cloneNode(true);
642	        }
643	        return child.cloneNode(true);
644	    }
645	
646	    /**
647	     * 编译一组节点并返回运行节点列表（**不挂载**，挂载由调用方处理）。
648	     *
649	     * 供 `engine.patch` 替换自身：updater 返回的 `string`/`Node` 经解析为 templateNodes，
650	     * 本方法编译它们（HTMLElement 走 `transformElement` 递归、文本插值走 `compileTextNode`），
651	     * `DocumentFragment` 展开成实际子节点，收集为 runtimeNodes 供调用方 `replaceWith`。
652	     *
653	     * @param nodes  待编译的模板节点（通常来自 `parseHtmlFragment` 或 updater 返回的 Node）
654	     * @param scope  顶层文本插值节点的注册 scope（替换后挂父下，用父 scope）
655	     */
656	    compileChildNodes(nodes: Node[], scope: AutoSparkScope | null): Node[] {
657	        const result: Node[] = [];
658	        for (const child of nodes) {
659	            const compiled = this.compileOneChild(child, scope);
660	            if (compiled == null) continue;
661	            if (compiled instanceof DocumentFragment) {
662	                result.push(...Array.from(compiled.childNodes));
663	            } else {
664	                result.push(compiled);
665	            }
666	        }
667	        return result;
668	    }
669	
670	    /**
671	     * 编译某模板的全部子节点并挂到指定父元素，返回已编译节点列表。
672	     *
673	     * 共享给结构指令（eager x-if 编译/重建子树 / x-for 项 / engine.data 重建子树 / `engine.patch`
674	     * 子树重建）：单节点编译委托 `compileOneChild`，挂载用 `appendChild`。`compileTextNode` 可能
675	     * 返回 `DocumentFragment`（多段插值）或 `null`（x-text 在场剪枝）：fragment 搬入父后展开成实际
676	     * 子节点入 `nodes`（供 if.ts 精确移除）；null 跳过（剪枝）。
677	     *
678	     * @param scope 子树根的 scope，供直接文本子节点插值注册（项 scope / x-if scope 等）
679	     */
680	    compileSubtree(
681	        parentEl: HTMLElement,
682	        templateEl: HTMLElement,
683	        scope: AutoSparkScope,
684	    ): ChildNode[] {
685	        const nodes: ChildNode[] = [];
686	        for (const child of Array.from(templateEl.childNodes)) {
687	            const compiled = this.compileOneChild(child, scope);
688	            if (compiled == null) continue; // 剪枝（如 x-text 在场的插值文本）
689	            if (compiled instanceof DocumentFragment) {
690	                // fragment：搬入父后展开成实际子节点入 nodes（供调用方精确移除）
691	                const moved = Array.from(compiled.childNodes);
692	                parentEl.appendChild(compiled);
693	                nodes.push(...moved);
694	            } else {
695	                // 非 fragment：HTMLElement/Text/Comment 等均为 ChildNode（可被调用方 remove）
696	                parentEl.appendChild(compiled);
697	                nodes.push(compiled as ChildNode);
698	            }
699	        }
700	        return nodes;
701	    }
702	
703	    /**
704	     * 供 x-for 编译单个列表项的模板。
705	     *
706	     * 手动建根 scope 并注入 localData（item/index），再用 transformElement
707	     * 递归编译其子节点（嵌套 scope 经 _linkParent 挂为本 scope 子代并继承 localData）。
708	     *
709	     * @param itemTemplate 单个项的模板元素（x-for 子模板的克隆）
710	     * @param parentScope  x-for 所在 scope，项 scope 挂为其子（删项时递归销毁）
711	     * @param localData   注入该项的局部变量（{ item, index }）
712	     * @param reuseEl      复用既有项根 DOM 节点（移动复用场景）；缺省则克隆模板。
713	     *                     复用时保留项根节点身份（保住项根本身的焦点/属性），但其子树 DOM 会被
714	     *                     清空重建（旧 scope 已销毁）→ 子节点焦点丢失，彻底保留需 core 对象身份订阅。
715	     */
716	    /**
717	     * 注入组件语义到既有 scope（ADR-0022 决策二/三）。
718	     *
719	     * 供 x-use 复用宿主 scope 化身组件实例（宿主 scope 本身即组件实例 scope，不另建），以及
720	     * compileChild 在新建 scope 后调用。注入内容：
721	     * - `isComponent=true` + `componentName=def.name`；
722	     * - `data`：data() 默认值先注入、props 后覆盖（R1=A 合并顺序），写入响应式 `$scopes[id]` 域；
723	     * - `methods`：注入 `scope.actions`（复用 x-on action 查找）；
724	     * - `hooks`：克隆到 `scope.hooks`（四阶段生命周期，每阶段数组克隆避免多实例共享引用）。
725	     *
726	     * @param scope 目标 scope（x-use 的宿主 scope，或 compileChild 新建的 scope）
727	     * @param def   组件定义
728	     * @param props x-use 传入的 props（覆盖 data() 默认值；undefined 则只注入默认值）
729	     */
730	    injectComponentSemantics(
731	        scope: AutoSparkScope,
732	        def: ComponentDef,
733	        props?: Record<string, any>,
734	    ): void {
735	        scope.isComponent = true;
736	        scope.componentName = def.name;
737	        const scopes = (this.engine.store.state as Record<string, any>)[SCOPES_KEY] as Record<
738	            string,
739	            any
740	        >;
741	        const hasComponentData = !!def.setup?.data;
742	        if (hasComponentData || props) {
743	            if (!scopes[scope.id]) scopes[scope.id] = {};
744	            const data = scopes[scope.id];
745	            scope._data = data;
746	            // 1) 组件 data() 默认值（先）
747	            if (hasComponentData) {
748	                try {
749	                    const defaults = def.setup!.data!();
750	                    if (defaults && typeof defaults === "object") Object.assign(data, defaults);
751	                } catch (e: any) {
752	                    this.engine.logger.warn(
753	                        `x-component "${def.name}" data() 执行失败，跳过默认值: ${e?.message ?? e}`,
754	                    );
755	                }
756	            }
757	            // 2) x-use props（后覆盖同名键，R1=A）
758	            if (props) Object.assign(data, props);
759	            // 失效 scope 的 _scopeView 缓存：宿主 scope 可能已缓存了 data 注入前的聚合视图
760	            // （如 x-use 宿主在 compileElement 阶段构建 _scopeView），注入 data 后须重建，否则
761	            // 后代 watch 经 getContext 读不到新 data 字段（与 DataDirective.invalidateScopeView 同理）。
762	            scope.invalidateScopeView();
763	        }
764	        // methods 注入 scope.methods（ADR-0022 决策二-3 修订：从 action 剥离为独立机制，
765	        // 不再进 scope.actions）。method 经 getMethod（组件边界）查找、getMethodThis（Proxy）调用。
766	        if (def.setup?.methods) {
767	            scope.methods = { ...def.setup.methods };
768	        }
769	        // locals 注入 scope._locals（ADR-0022 决策二-3 (10)：非响应式局部变量，不进聚合视图）。
770	        // 经 Proxy this 的 this.<key> 读写（method/data/framework 优先级高于 _locals）。
771	        if (def.setup?.locals) {
772	            scope._locals = { ...def.setup.locals };
773	        }
774	        // hooks 克隆到 scope.hooks（每阶段函数数组克隆，避免多实例共享同一数组引用）
775	        if (def.hooks) {
776	            scope.hooks = {
777	                created: def.hooks.created.slice(),
778	                mounted: def.hooks.mounted.slice(),
779	                beforeUnmount: def.hooks.beforeUnmount.slice(),
780	                unmounted: def.hooks.unmounted.slice(),
781	            };
782	        }
783	    }
784	
785	    /**
786	     * 实例化组件到既有 scope（ADR-0022 决策五，供 x-use）。
787	     *
788	     * 宿主 scope 化身组件实例（T4=B 宿主化身组件根），步骤：
789	     * 1. 注册组件快照根到 templateScopeMap（映射到宿主 scope），使快照子树编译时 _linkParent 能找到宿主 scope；
790	     * 2. 注入组件语义（data/methods/hooks）到宿主 scope；
791	     * 3. compileSubtree 编译组件快照子树到宿主元素（快照内指令建子 scope，watch 时读到注入的 data）；
792	     * 4. 补触发 created/mounted hooks（宿主 compile() 早于组件注入，hooks 须补触发）；
793	     * 5. flush 调度器消化首次渲染。
794	     *
795	     * @param hostScope   宿主 scope（化身组件实例 scope）
796	     * @param snapshot    组件冻结快照根
797	     * @param def         组件定义（可空：纯快照组件无 setup）
798	     * @param props       x-use 传入的 props（覆盖 data() 默认）
799	     */
800	    instantiateComponent(
801	        hostScope: AutoSparkScope,
802	        snapshot: HTMLElement,
803	        def: ComponentDef | null,
804	        props?: Record<string, any>,
805	    ): void {
806	        // 1. 注册快照根到 templateScopeMap：子树编译时 _linkParent 沿 parentElement 找到此映射 → 宿主 scope
807	        this.templateScopeMap.set(snapshot, hostScope);
808	        // 2. 注入组件语义
809	        if (def) {
810	            this.injectComponentSemantics(hostScope, def, props);
811	        } else if (props) {
812	            this.injectInitialData(hostScope, props);
813	        }
814	        const hostEl = hostScope.el!;
815	        // 2.5 响应式 <style> bind 订阅（ADR-0022 决策四-4.1）：须在 data 注入（步骤2）后、compileSubtree 前。
816	        // 遍历 def.styleBinds 调 hostScope.watch——watcher 进 scope.watchers，随 scope.destroy 自动 off（零额外卸载接线）。
817	        // 首求值立即收集依赖并写首值；created hook 若在步骤4 改 data，会触发 watcher 重求值更新变量（响应式自动回流）。
818	        // 变量挂组件根元素 hostEl（每实例独立，与 data-cmp-{id} 同构隔离）；null/undefined 不写走 var(--name, unset) 回退。
819	        if (def?.styleBinds && def.styleBinds.length > 0) {
820	            this._bindStyleVars(hostScope, hostEl, def.styleBinds);
821	        }
822	        // 3. 编译快照子树到宿主元素（hostScope.el）
823	        this.compileSubtree(hostEl, snapshot, hostScope);
824	        // 3.5 组件作用域 CSS（ADR-0022 决策四-4）：给组件根+后代打 data-cmp-{id} 属性 + 注入改写后的样式
825	        if (def?.styles && def.styles.length > 0) {
826	            mountComponentScopedAttr(hostEl, hostScope.id);
827	            injectComponentStyle(def.name, def.styles, hostScope.id);
828	        }
829	        // 4. 补触发组件 created/mounted hooks
830	        if (def) {
831	            hostScope["_runHooks"]("created");
832	            hostScope["_runHooks"]("mounted");
833	        }
834	        // 5. flush 首次渲染
835	        this.engine.scheduler.flushAll();
836	    }
837	
838	    /**
839	     * 为组件实例的 `<style>` bind 建立 CSS 变量订阅（ADR-0022 决策四-4.1）。
840	     *
841	     * 遍历 `def.styleBinds`，对每个 bind 调 `hostScope.watch(expr)`——watch 返回当前值做首写、
842	     * watcher 进 `hostScope.watchers`（随 scope.destroy 自动 off，零额外卸载接线）。
843	     * 求值结果经 `coerceStyleValue` 归一化后写入组件根元素的 CSS 变量：null/undefined 不写
844	     * （removeProperty，CSS 走 `var(--name, unset)` 回退），其余 `String(value)` 写入。
845	     *
846	     * @param scope  组件实例 scope（watcher 寄主，destroy 时统一 off）
847	     * @param rootEl 组件根元素（变量挂载点，每实例独立）
848	     * @param binds  bind 清单（编译期提取、多实例共享只读）
849	     */
850	    private _bindStyleVars(
851	        scope: AutoSparkScope,
852	        rootEl: HTMLElement,
853	        binds: StyleBind[],
854	    ): void {
855	        const apply = (varName: string, value: unknown) => {
856	            const coerced = coerceStyleValue(value);
857	            if (coerced == null) {
858	                rootEl.style.removeProperty(varName);
859	            } else {
860	                rootEl.style.setProperty(varName, coerced);
861	            }
862	        };
863	        for (const b of binds) {
864	            // watch 返回首值（同步求值 + 收集依赖），但首次 flush 前回调未触发——
865	            // 须用返回值手动写首值，否则首帧变量缺失（listener 仅在状态变化 flush 时才回调）。
866	            const first = scope.watch(b.expr, ({ value }) => apply(b.varName, value));
867	            apply(b.varName, first);
868	        }
869	    }
870	
871	    /**
872	     * 仅注入响应式 data（无组件语义，ADR-0021 决策 12-c 保留路径）。
873	     *
874	     * 供 x-loading 等非组件消费者：把 initialData 写入 `store.state.$scopes[scope.id]` 并令 scope.data
875	     * 指向它。块内指令 watch 首次求值即收集到 `$scopes.<id>.<field>` 精准路径。
876	     */
877	    injectInitialData(scope: AutoSparkScope, initialData: Record<string, any>): void {
878	        const scopes = (this.engine.store.state as Record<string, any>)[SCOPES_KEY] as Record<
879	            string,
880	            any
881	        >;
882	        if (!scopes[scope.id]) scopes[scope.id] = {};
883	        const data = scopes[scope.id];
884	        scope._data = data;
885	        Object.assign(data, initialData);
886	    }
887	
888	    compileChild(
889	        itemTemplate: HTMLElement,
890	        parentScope: AutoSparkScope | null,
891	        localData: Record<string, any> | null,
892	        reuseEl?: HTMLElement,
893	        /**
894	         * 编译前注入块根的**响应式** data（仿 DataDirective.applyLocal）。
895	         *
896	         * 与 localData（普通对象、非响应式）并列：在 `scope.compile()` 之前把数据写入
897	         * `store.state.$scopes[scope.id]` 并令 `scope.data` 指向它。块内指令 watch 首次求值时，
898	         * `getContext` 的 `_scopeView` 缓存即建成含 data 层的 Proxy，`collectDependencies`
899	         * 收集到 `$scopes.<id>.<field>` 精准路径——后续 `Object.assign` 进该响应式代理即字段级细粒度更新。
900	         *
901	         * 供 x-loading 等消费者把 config 注入块（ADR-0021 决策 12-c）；x-use 实例化组件时传入 props
902	         *（决策二-2，作为组件 data 域的覆盖值，后于 componentDef.data() 注入）。无此参则不注入 data。
903	         */
904	        initialData?: Record<string, any>,
905	        /**
906	         * 组件定义（ADR-0022 决策二/三）：x-use 实例化组件时传入，注入组件语义：
907	         * - `data()`：先于 initialData 注入 scope.data（默认值，被 props 覆盖，决策 R1=A 合并顺序）；
908	         * - `methods`：注入 scope.actions（复用 x-on action 查找，this=ComponentMethodContext）；
909	         * - `hooks`：克隆到 scope.hooks（四阶段生命周期，compile/destroy 时触发）。
910	         * 无此参（x-for/loading 等非组件场景）则跳过组件语义注入。
911	         */
912	        componentDef?: ComponentDef,
913	    ): { el: HTMLElement; scope: AutoSparkScope } {
914	        const el = reuseEl ?? (itemTemplate.cloneNode(false) as HTMLElement);
915	        if (!reuseEl) removeDirectives(el, "x-", this._runtimeKeepAttr());
916	        // reuseEl：旧 scope 已 destroy，其子树 DOM 残留在 el 上，须清空后重建，否则 compileSubtree
917	        // 的 appendChild 会导致子节点重复。
918	        if (reuseEl) {
919	            while (el.firstChild) el.removeChild(el.firstChild);
920	        }
921	        const scope = new AutoSparkScope(this.engine, el, itemTemplate);
922	        scope.locals = localData;
923	        // 组件语义注入（须早于 scope.compile()——created hook 与各指令 watch 首次求值须读到完整 data/actions）。
924	        // data 合并顺序 R1=A：componentDef.data() 先注入默认，initialData（x-use props）后覆盖。
925	        if (componentDef) {
926	            this.injectComponentSemantics(scope, componentDef, initialData);
927	        } else if (initialData) {
928	            // 非组件场景（x-loading 等消费者）仅注入 initialData 到响应式 data 域（无 data()/methods/hooks）
929	            this.injectInitialData(scope, initialData);
930	        }
931	        // parentScope 可空（rootless 块编译，如 x-loading 宿主无 scope 的动态插入场景）：跳过父子挂接，
932	        // 块 scope 独立（无祖先继承），仅靠 initialData 注入的 data 提供上下文。
933	        parentScope?.addChild(scope);
934	        this.templateScopeMap.set(itemTemplate, scope);
935	        this.engine.scopes.set(new WeakRef(el), scope);
936	        // 项根本身若是结构指令（嵌套 x-for，如 <ul x-for="row"><li x-for="cell">），
937	        // 其子节点由该内层结构指令在 render 时自行克隆编译，此处跳过手动编译以免双重冲突。
938	        if (!this._resolveOwnership(scope)) {
939	            this.compileSubtree(el, itemTemplate, scope);
940	        }
941	        scope.compile();
942	        // 项根属性插值 desugar（项根不走 compileElement，须在此补；复用 BindDirective）
943	        this._compileAttrInterpolation(el, scope);
944	        // x-model 元数据自动注入（ADR-0020）：项根含 x-model 时同样合成
945	        this._synthesizeModelSchemaBindings(el, scope);
946	        return { el, scope };
947	    }
948	
949	    /**
950	     * 向上查找最近的已注册指令祖先 scope，把 scope 挂为其子，
951	     * 并继承祖先的 localData（让 item/index 向嵌套子元素传递）。
952	     */
953	    private _linkParent(template: HTMLElement, scope: AutoSparkScope): void {
954	        let p: HTMLElement | null = template.parentElement;
955	        while (p) {
956	            const parentScope = this.templateScopeMap.get(p);
957	            if (parentScope) {
958	                parentScope.addChild(scope);
959	                if (parentScope.locals) scope.locals = parentScope.locals;
960	                return;
961	            }
962	            p = p.parentElement;
963	        }
964	    }
965	}
