218	export class LoadingDirective extends AutoSparkDirectiveBase implements RuntimeDirective {
219	    /** 运行时指令：走 observer 通道（由 engine 级 RuntimeObserverDispatcher 驱动，见 ADR-0003 决策 7） */
220	    static override readonly kind = DirectiveKind.Runtime;
221	
222	    /**
223	     * 类级初始化：注入全局样式。
224	     *
225	     * observer 通道（observer + 实例表 + 初始扫描）已移交 engine 级 RuntimeObserverDispatcher，
226	     * 指令不再自建。样式注入须在 dispatcher 初始扫描（触发首次 mounted → mountOverlay）**之前**完成
227	     * ——FOUC 防御；initializeAll 在 dispatcher.start() 之前调用，顺序保证。幂等（stylesInjected）。
228	     */
229	    static override initialize(_engine: AutoSpark): void {
230	        injectStyles();
231	    }
232	
233	    /** 当前已挂载的覆盖层（= 编译后的块根；未挂载时为 null）；delay 窗口期内仍为 null */
234	    private overlay: HTMLElement | null = null;
235	    /** 已挂载覆盖层对应的块 scope（attrChanged 细粒度 patch 其 data；unmount 时 destroy） */
236	    private blockScope: AutoSparkScope | null = null;
237	    /** delay 定时器句柄（延迟挂载未触发时存在） */
238	    private delayTimer: ReturnType<typeof setTimeout> | null = null;
239	    /** 解析后的配置（mounted 中赋值，definite assignment） */
240	    private config!: LoadingConfig;
241	    /** value 当前值的读取函数（路径支路 getVal / 表达式支路 with(state) 求值） */
242	    private _read!: () => any;
243	    /** 未注册名的合成透传 descriptor 缓存（按名复用，ADR-0038 决策 4；随实例生死） */
244	    private _synthetics: Map<string, ActionDesc> = new Map();
245	
246	    /** 元素挂载（dispatcher 检测到 add / 初始扫描）：解析配置 + 字面量/反应式分流 + 首渲 */
247	    override mounted(): void {
248	        this.config = this.parseConfig();
249	        // 字面量模式：裸 x-loading ≡ "true"、显式 "true"/"false" 为特殊布尔值（非状态路径）→ 静态显隐，无订阅
250	        const literal = this.resolveLiteral(this.config.value);
251	        if (literal !== null) {
252	            this.toggle(literal);
253	            return;
254	        }
255	        // 反应式模式：value 为全局 store 路径/表达式
256	        this._bindValue();
257	        this.toggle(!!this._read());
258	    }
259	
260	    /**
261	     * 判定 value 是否为字面量布尔。
262	     *
263	     * - 空（裸 `x-loading` / 未指定 value）≡ `true`：符合"加了就显示"的直觉；
264	     * - `true` / `false`（大小写不敏感）为特殊布尔字面量，**非**状态路径——便于静态快速控制显隐；
265	     * - 其余返回 null → 走反应式（`engine.store` 全局路径/表达式）。
266	     *
267	     * @returns true/false 表示字面量静态显隐；null 表示走反应式订阅
268	     */
269	    private resolveLiteral(value: string): boolean | null {
270	        const v = (value ?? "").trim();
271	        if (v === "") return true; // 裸属性 / 缺省 ≡ true
272	        const lv = v.toLowerCase();
273	        if (lv === "true") return true;
274	        if (lv === "false") return false;
275	        return null;
276	    }
277	
278	    /** 元素移除（dispatcher 检测到 remove）：清理订阅 / 定时器 / 覆盖层 DOM */
279	    override unmounted(): void {
280	        this._teardown();
281	    }
282	
283	    /**
284	     * 属性值变化（dispatcher 检测到 setAttribute）：细粒度 patch，不重编译块（ADR-0021 决策 12-(d)）。
285	     *
286	     * 解析新 config 后：
287	     * - **视觉字段**（message/color/bgColor/opacity）→ `Object.assign` 进块 data，块内绑定经
288	     *   响应式字段级细粒度更新；同时重算壳样式（bg/opacity 既是 data 值、又是 overlay 背景）写回块根；
289	     * - **value** → 重判显隐（show/hide），delay 重置定时器；
290	     * - **selector** → 变化需移位，重建 overlay（块随之重编译重注入）。
291	     *
292	     * 仅当 selector 变化（须移位）或覆盖层尚未挂载时走重建；否则走细粒度 patch，保留已编译块。
293	     */
294	    /**
295	     * 属性值变化（dispatcher 检测到 setAttribute）：重建 overlay（ADR-0021 决策 12-d）。
296	     *
297	     * 解析新 config 后整体 teardown + remount：块随新 config 重新编译、data 重新注入、
298	     * 壳样式重算。**不细粒度 patch 既有块**——attrChanged 是编程式 setAttribute 的罕见路径，
299	     * 重建最简且正确（避免块已编译的 data/订阅与 dispatcher 时序耦合）。块内 message/color
300	     * 等随新 config 重新编译即取新值。
301	     */
302	    attrChanged(newVal: string, _oldVal?: string): void {
303	        this.value = newVal;
304	        if (this.info) this.info.value = newVal;
305	        this.config = this.parseConfig();
306	        this._teardown();
307	        // 字面量模式：裸/true/false 静态显隐，无订阅
308	        const literal = this.resolveLiteral(this.config.value);
309	        if (literal !== null) {
310	            this.toggle(literal);
311	            return;
312	        }
313	        this._bindValue();
314	        this.toggle(!!this._read());
315	    }
316	
317	    /**
318	     * 建立 value 订阅（engine.store 全局，无 scope）。
319	     *
320	     * - 路径支路（isSimpleStatePath）→ `store.watch(path)` 精准订阅，`getVal` 读当前值；
321	     * - 表达式支路（如 `a && !b`）→ `collectDependencies` 收集读依赖后订阅（仅全局 state，
322	     *   不支持 scope 局部变量）。回调经 toggle 显隐。
323	     */
324	    private _bindValue(): void {
325	        const store = this.engine.store;
326	        const expr = this.config.value;
327	        const onChange = () => this.toggle(!!this._read());
328	        if (isSimpleStatePath(expr)) {
329	            this._read = () => getVal(store.state, expr);
330	            this.watchers.push(store.watch(expr, onChange));
331	        } else {
332	            const getter = new Function("scope", `with(scope){ return (${expr}); }`) as (scope: any) => any;
333	            this._read = () => {
334	                try {
335	                    return getter(store.state);
336	                } catch (e: any) {
337	                    this.warn(`x-loading: eval "${expr}" failed: ${e?.message ?? e}`);
338	                    return undefined;
339	                }
340	            };
341	            const deps = store.collectDependencies(() => {
342	                this._read();
343	            }, "read");
344	            this.watchers.push(store.watch(deps, onChange));
345	        }
346	    }
347	
348	    /** 清理本实例全部资源：off watcher + 清 delay 定时器 + 销毁块 scope + 移除覆盖层 DOM */
349	    private _teardown(): void {
350	        for (const w of this.watchers) {
351	            try {
352	                (w as Watcher).off?.();
353	            } catch {
354	                /* 忽略已 off 的 watcher */
355	            }
356	        }
357	        this.watchers.length = 0;
358	        if (this.delayTimer) {
359	            clearTimeout(this.delayTimer);
360	            this.delayTimer = null;
361	        }
362	        if (this.blockScope) {             // 销毁块 scope（off 块内 watcher）+ 回收其私有响应式域 $scopes[id]
363	            const id = this.blockScope.id;
364	            this.blockScope.destroy();
365	            const scopes = (this.engine.store.state as Record<string, any>)[SCOPES_KEY] as
366	                | Record<string, any>
367	                | undefined;
368	            if (scopes) delete scopes[id];
369	            this.blockScope = null;
370	        }
371	        if (this.overlay) {
372	            this.overlay.remove();
373	            this.overlay = null;
374	        }
375	    }
376	
377	    /**
378	     * 解析指令值：对象语法 → 配置绑定；否则 → 快速绑定（整值即 value）。
379	     *
380	     * 指令选项层（`x-loading-options`，ADR-0007 解析期合并进 `this.options`）承载**视觉字段**
381	     * 补充配置（message/color/bgColor/opacity/delay/selector）——异步源指令（x-data/x-html）
382	     * 合成的 `loading:{...}` 选项经此接线生效（ADR-0033/0035）。合并方向：属性值**内联声明
383	     * 优先**（`x-loading="{value,...}"` 是主语义，`-options` 是补充层，不覆盖主声明）。
384	     */
385	    private parseConfig(): LoadingConfig {
386	        const raw = String(this.value ?? "").trim();
387	        const inline: LoadingConfig = raw.startsWith("{") ? this.parseObject(raw) : { value: raw };
388	        const opt = this.options;
389	        if (!opt || typeof opt !== "object") return inline;
390	        for (const key of ["message", "bgColor", "color", "opacity", "delay", "selector", "actions"] as const) {
391	            const v = (opt as Record<string, any>)[key];
392	            if (v !== undefined && (inline as Record<string, any>)[key] === undefined) {
393	                (inline as Record<string, any>)[key] = v;
394	            }
395	        }
396	        return inline;
397	    }
398	
399	    /** 解析对象配置（relaxedToJson）；非对象/抛错 → warn + 空 value */
400	    private parseObject(raw: string): LoadingConfig {
401	        try {
402	            const parsed: unknown = JSON.parse(relaxedToJson(raw));
403	            if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
404	                this.warn(`x-loading: 对象配置必须解析为对象，得到 ${JSON.stringify(parsed)}`);
405	                return { value: "" };
406	            }
407	            const obj = parsed as Record<string, any>;
408	            // 旧键 visible 已更名为 value：warn 提示迁移、忽略不生效（缺失 value ≡ 裸属性恒显示）
409	            if (obj.visible !== undefined) {
410	                this.warn(`x-loading: 配置键 "visible" 已更名为 "value"，该键被忽略`);
411	            }
412	            return {
413	                value: typeof obj.value === "string" ? obj.value : "",
414	                message: typeof obj.message === "string" ? obj.message : undefined,
415	                bgColor: typeof obj.bgColor === "string" ? obj.bgColor : undefined,
416	                color: typeof obj.color === "string" ? obj.color : undefined,
417	                opacity: typeof obj.opacity === "number" ? obj.opacity : undefined,
418	                delay: typeof obj.delay === "number" ? obj.delay : undefined,
419	                selector: typeof obj.selector === "string" ? obj.selector : undefined,
420	                actions: this._parseActionNames(obj.actions),
421	            };
422	        } catch (e: any) {
423	            this.warn(`x-loading: 对象配置解析失败: ${e?.message ?? e}`);
424	            return { value: "" };
425	        }
426	    }
427	
428	    /** 显隐总入口 */
429	    private toggle(show: boolean): void {
430	        if (show) this.show();
431	        else this.hide();
432	    }
433	
434	    /**
435	     * 显示覆盖层。
436	     *
437	     * 已挂载（overlay 非空）或延迟窗口期内（delayTimer 非空）直接返回，防重复。
438	     * delay>0 时 setTimeout 延迟挂载；否则立即挂载。
439	     */
440	    private show(): void {
441	        if (this.overlay || this.delayTimer) return;
442	        const delay = this.config.delay ?? DEFAULTS.delay;
443	        if (delay > 0) {
444	            this.delayTimer = setTimeout(() => {
445	                this.delayTimer = null;
446	                this.mountOverlay();
447	            }, delay);
448	            return;
449	        }
450	        this.mountOverlay();
451	    }
452	
453	    /**
454	     * 隐藏：取消未触发的延迟挂载；移除已挂载的覆盖层（含块 scope 回收）。
455	     *
456	     * delay 窗口内回 false → 定时器取消、覆盖层从未挂载（防闪烁）。已挂载则销毁块 scope +
457	     * 移除覆盖层 DOM（重建式显隐，非 display 隐藏——与既有语义一致）。
458	     */
459	    private hide(): void {
460	        if (this.delayTimer) {
461	            clearTimeout(this.delayTimer);
462	            this.delayTimer = null;
463	        }
464	        if (this.blockScope) {
465	            const id = this.blockScope.id;
466	            this.blockScope.destroy();
467	            const scopes = (this.engine.store.state as Record<string, any>)[SCOPES_KEY] as
468	                | Record<string, any>
469	                | undefined;
470	            if (scopes) delete scopes[id];
471	            this.blockScope = null;
472	        }
473	        if (this.overlay) {
474	            this.overlay.remove();
475	            this.overlay = null;
476	        }
477	    }
478	
479	    /**
480	     * 构建并挂载覆盖层（= 编译后的组件根）到目标元素（ADR-0022 承接 ADR-0021 决策 12）。
481	     *
482	     * 渲染统一走「编译组件」路径：取组件 = `getComponent('loading') ?? DEFAULT_BLOCK`，深克隆 → 经 compileChild
483	     * 编译挂载（parentScope 为宿主 scope 使组件继承宿主数据上下文；**config 经 compileChild 第 5 参      * initialData 在 compile 前注入 data**，确保组件内 watch 首次求值即收集到 `$scopes.<id>.<field>`
484	     * 精准路径，后续 attrChanged 可字段级细粒度更新）→ 注入壳样式到组件根 → 挂到 target。
485	     */
486	    private mountOverlay(): void {
487	        if (this.overlay) return;
488	        const target = this.resolveTarget();
489	        if (!target) return;
490	
491	        // 取组件快照：自定义 loading 组件（沿宿主 scope 链就近 + 全局兜底），未命中用 DEFAULT_BLOCK
492	        const snapshot = this._resolveLoadingComponent();
493	        const clone = snapshot.cloneNode(true) as HTMLElement;
494	
495	        // config 视图：七字段，作为块根 data 在 compile 前注入（响应式，块内 x-text="message" 取用）
496	        const initialData = this._configData();
497	        // 编译块：parentScope = 宿主 scope（继承宿主数据上下文）；宿主无 scope（动态插入等）传 null
498	        // —— compileChild 支持空 parentScope，块 scope 独立、仅靠 initialData 的 data 提供上下文
499	        const parentScope = this.engine.findScopeByEl(this.el!) ?? null;
500	        const compiled = this.engine.compiler.compileChild(
501	            clone,
502	            parentScope,
503	            {},
504	            undefined,
505	            initialData,
506	        );
507	        const overlay = compiled.el;
508	        this.blockScope = compiled.scope;
509	
510	        // 块根即 overlay 壳：注入壳样式（定位/背景/zindex/screen），追加在块作者声明样式之后
511	        this._applyShellStyle(overlay);
512	
513	        target.appendChild(overlay);
514	        this.overlay = overlay;
515	
516	        // 动作按钮点击委托（ADR-0038 决策 3）：块内 [data-action] 元素点击触发对应 action。
517	        // 监听器挂在 overlay 元素上，随元素生死（hide/teardown 移除元素即回收，无需显式解绑）。
518	        overlay.addEventListener("click", (e) => this._onOverlayClick(e, compiled.scope));
519	    }
520	
521	    /**
522	     * 解析 loading 块快照：自定义块优先（宿主 scope 链 + 全局兜底），未命中回退 DEFAULT_BLOCK。
523	     *
524	     * DEFAULT_BLOCK 是字符串模板，每次解析为新的根元素（无缓存需求——仅作兜底，自定义组件才走
525	     * engine 全局缓存）。返回的快照形态与自定义组件一致（含 x-component、未编译、保留指令属性）。
526	     */
527	    private _resolveLoadingComponent(): HTMLElement {
528	        if (this.el) {
529	            const custom = this.engine.getComponent(this.el, "loading");
530	            if (custom) return custom;
531	        }
532	        // DEFAULT_BLOCK 字符串 → 解析取单根元素（parseHtmlFragment 已 trim，单顶级元素）
533	        const frag = parseHtmlFragment(DEFAULT_BLOCK);
534	        const root = (frag?.firstElementChild as HTMLElement | null) ?? null;
535	        if (root) return root;
536	        // 兜底（DEFAULT_BLOCK 解析失败，理论上不可达）：建空 overlay 防 NPE
537	        const fallback = document.createElement("div");
538	        fallback.className = OVERLAY_CLASS;
539	        return fallback;
540	    }
541	
542	    /**
543	     * 注入覆盖层壳样式到块根（决策 12-(b)）：定位/铺满/背景/zindex/screen。
544	     *
545	     * 追加在块作者声明样式之后（覆盖定位冲突）。「覆盖层」语义由指令保证，块作者只管装内容。
546	     * screen 修饰符 → position:fixed 撑满视口；否则 position:absolute 撑满宿主（须宿主定位）。
547	     */
548	    private _applyShellStyle(overlay: HTMLElement): void {
549	        const bgColor = this.config.bgColor ?? DEFAULTS.bgColor;
550	        const opacity = this.config.opacity ?? DEFAULTS.opacity;
551	        const screen = this.modifiers?.includes("screen");
552	        overlay.style.position = screen ? "fixed" : "absolute";
553	        overlay.style.inset = "0";
554	        overlay.style.display = "flex";
555	        overlay.style.alignItems = "center";
556	        overlay.style.justifyContent = "center";
557	        overlay.style.zIndex = String(DEFAULTS.zIndex);
558	        // 遮罩底色 + alpha：映射为 bgColor 的 alpha 通道（非元素 opacity，保证 loader/文字清晰）
559	        overlay.style.background = rgba(bgColor, opacity);
560	    }
561	
562	    /**
563	     * 构造注入块 data 的 config 视图（八字段：原七字段 + actions，决策 12-(c) Q7 / ADR-0038 决策 2）。
564	     *
565	     * `value` 是表达式串（如 `"order.isSubmit"`）——块内若 x-if="value" 期待布尔会拿到字符串，
566	     * 属已知脚枪（value 是宿主显隐逻辑，控制 overlay 挂载与否，非块内消费字段），文档已标注。
567	     * `actions` 为挂载时解析的动作按钮视图 `[{name, title}]`（见 {@link _actionsData}）。
568	     */
569	    private _configData(): Record<string, any> {
570	        return {
571	            value: this.config.value,
572	            message: this.config.message ?? "",
573	            bgColor: this.config.bgColor ?? DEFAULTS.bgColor,
574	            color: this.config.color ?? DEFAULTS.color,
575	            opacity: this.config.opacity ?? DEFAULTS.opacity,
576	            delay: this.config.delay ?? DEFAULTS.delay,
577	            selector: this.config.selector ?? "",
578	            actions: this._actionsData(),
579	        };
580	    }
581	
582	    /**
583	     * 解析动作按钮数据视图：`[{name, title}]`（ADR-0038 决策 2）。
584	     *
585	     * 挂载时经 getAction 链解析 `title = ActionDesc.title ?? name`（内置 close 自带「关闭」，
586	     * 后注册的显示 name 兜底——快照语义、不做响应式追踪，attrChanged 重建时重新解析）。
587	     * 查找基准与 parentScope 同源（宿主 scope 链；宿主无 scope 时直接查全局表）。
588	     */
589	    private _actionsData(): Array<{ name: string; title: string }> {
590	        const names = this.config.actions ?? [];
591	        const scope = this.el ? this.engine.findScopeByEl(this.el) : null;
592	        return names.map((name) => ({
593	            name,
594	            title: (scope?.getAction(name) ?? this.engine.actions[name])?.title ?? name,
595	        }));
596	    }
597	
598	    /**
599	     * 校验 actions 配置字段：须为字符串数组（ADR-0038 决策 1）。
600	     *
601	     * 非数组 / 缺失 → undefined（无按钮行）；数组内非（非空）字符串元素 warn 剪枝。
602	     */
603	    private _parseActionNames(raw: unknown): string[] | undefined {
604	        if (raw === undefined || raw === null) return undefined;
605	        if (!Array.isArray(raw)) {
606	            this.warn(`x-loading: 配置键 "actions" 须为字符串数组，已忽略`);
607	            return undefined;
608	        }
609	        return raw.filter((v) => {
610	            const ok = typeof v === "string" && v.trim() !== "";
611	            if (!ok) {
612	                this.warn(
613	                    `x-loading: actions 数组元素须为非空字符串，已剪枝: ${JSON.stringify(v)}`,
614	                );
615	            }
616	            return ok;
617	        });
618	    }
619	
620	    /**
621	     * 取未注册名的合成透传 descriptor（ADR-0038 决策 4，与 ADR-0036 决策 7 内置信号型同构）：
622	     * `{name, title: name, handle: (p) => p}` 经 buildAction 包装（local=false → 总线 + DOM 双发），
623	     * 按名缓存复用。让未注册名同样走完整双通道广播——pending+resolved 同 tick、无 rejected。
624	     */
625	    private _syntheticAction(name: string): ActionDesc {
626	        let desc = this._synthetics.get(name);
627	        if (!desc) {
628	            desc = buildAction((type, payload) => this.engine.emit(type as any, payload), {
629	                handle: (payload?: any) => payload,
630	                name,
631	            });
632	            this._synthetics.set(name, desc);
633	        }
634	        return desc;
635	    }
636	
637	    /**
638	     * 覆盖层级 click 委托（ADR-0038 决策 3）：块内任意 `data-action="<name>"` 元素点击即触发。
639	     *
640	     * 逐次现查（与 x-on「查找延迟到触发时」同哲学）：已注册走真 action（getAction 链——块
641	     * scope 的 parent 是宿主 scope，局部/全局 action 均可达），未注册走合成透传 descriptor，
642	     * 均以标准 AutoSparkActionContext（el=被点元素）调用 → buildAction 双通道广播。
643	     * 随后按 hide 约定键（决策 5，点击时现读 `desc.hide !== false`）自动隐藏（决策 6：
644	     * **先完整广播再移除**——监听方同步跑完；async 到 pending 即隐藏不等待 resolved）。
645	     */
646	    private _onOverlayClick(event: Event, scope: AutoSparkScope): void {
647	        const target = (event.target as HTMLElement | null)?.closest?.("[data-action]") as
648	            | HTMLElement
649	            | null;
650	        if (!target || !this.overlay?.contains(target)) return;
651	        const name = target.getAttribute("data-action");
652	        if (!name) return;
653	        const desc = scope.getAction(name) ?? this._syntheticAction(name);
654	        const ctx: AutoSparkActionContext = {
655	            el: target,
656	            $event: event,
657	            data: scope.getContext(),
658	            scope,
659	            store: this.engine.store,
660	            state: this.engine.store.state,
661	            engine: this.engine,
662	            $options: {},
663	        };
664	        try {
665	            desc.handle.call(ctx);
666	        } catch {
667	            /* buildAction 已广播 rejected 并 rethrow；此处吞防委托监听器 uncaught（对齐 OnDirective finalHandler） */
668	        }
669	        if (desc.hide !== false) this.hide();
670	    }
671	
672	    /**
673	     * 解析覆盖层挂载目标元素。
674	     *
675	     * - 无 selector → 宿主元素 `this.el`；
676	     * - selector 以 `@` 开头 → `document.querySelector(去@)`，支持挂到宿主外/全局元素；
677	     * - 其余 → `宿主.querySelector(selector)`，挂到宿主后代；
678	     * - 未命中 / 非法选择器 → 回退宿主（命中失败不抛错、记 warn）。
679	     */
680	    private resolveTarget(): HTMLElement | null {
681	        const host = this.el;
682	        if (!host) return null;
683	        const sel = this.config.selector;
684	        if (!sel) return host;
685	        const isGlobal = sel.startsWith("@");
686	        const query = isGlobal ? sel.slice(1) : sel;
687	        if (!query) return host; // 空 selector（如裸 "@"）→ 宿主
688	        try {
689	            const root: ParentNode = isGlobal ? document : host;
690	            const found = root.querySelector(query);
691	            return found instanceof HTMLElement ? found : host; // 未命中 → 回退宿主
692	        } catch (e: any) {
693	            // 非法选择器（querySelector 抛 SyntaxError）→ 回退宿主，避免中断
694	            this.warn(`x-loading: 非法 selector "${sel}"，回退到宿主元素: ${e?.message ?? e}`);
695	            return host;
696	        }
697	    }
698	}
