1	// oxlint-disable typescript/no-this-alias
2	import type { AutoSpark } from "./engine";
3	import type { ComponentHooks } from "./directives/component-def";
4	import type { ActionDesc } from "./actions/types";
5	import { AutoSparkDirectiveBase } from "./directives/base";
6	import { getVal, type Watcher } from "autostore";
7	import { getDirectives, getHostOptions } from "./directives/utils/getDirectives";
8	import { createDirectives } from "./directives/utils/createDirectives";
9	
10	/**
11	 * 简单状态路径：仅字母/数字/下划线/$ 组成的段，以点分隔。
12	 * 用于 watch/read 双轨分流——只对纯标识符路径走精准订阅，含空格/运算符/符号/通配符的
13	 * 一律走表达式支路（with 求值）。比 isStatePath（允许任意非点字符）更严格。
14	 */
15	const SIMPLE_PATH_RE = /^[\w$]+(?:\.[\w$]+)*$/;
16	
17	/**
18	 * 依赖路径集比较（排序后逐项比对）。collectDependencies 返回路径串数组，收集顺序即读取
19	 * 顺序——同一表达式不同分支的读取顺序天然不同，比较前排序以只关注集合差异。
20	 */
21	function depsEqual(a: unknown, b: unknown): boolean {
22	    if (a === b) return true;
23	    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
24	    const sa = [...a].sort();
25	    const sb = [...b].sort();
26	    return sa.every((p, i) => p === sb[i]);
27	}
28	
29	/** 纯状态路径判定。导出供指令复用（x-for 据此判断 itemsPath 是否纯路径，
30	 *  决定是否补 `items.*` 项级监听——表达式 itemsPath 已由 watchExpression 覆盖）。 */
31	export function isSimpleStatePath(value: string): boolean {
32	    return SIMPLE_PATH_RE.test(value);
33	}
34	
35	export type AutoSparkBindingOptions = {
36	    /** 引用模板元素（编译只读输入，保留指令属性） */
37	    template: HTMLElement;
38	    /** 引用实际渲染的元素（已移除指令属性） */
39	    el: HTMLElement;
40	    /** 该元素上的指令实例列表 */
41	    directives: AutoSparkDirectiveBase[];
42	};
43	
44	/**
45	 * 指令更新回调：接收当前最新值。
46	 *
47	 * 注意：回调在 `scheduler` flush 时触发，传入的 `value` 是**重新求值后的当前值**，
48	 * 反映本 tick 内所有变更的累积结果（而非某一次 operate 的值）。
49	 */
50	export type ScopeWatchListener = (payload: { value: any }) => void;
51	
52	/**
53	 * watch 的订阅选项（仅路径支路生效，透传给 `store.watch`，ADR-0043）。
54	 *
55	 * - `depth`：向后代钻取的深度（autostore 三档语义：0=仅自身重赋值、1=自身+恰好一级后代、
56	 *   ≥2=自身+全部后代）。属性展开（`x-bind="obj"` 无参）用它订阅对象内部键的变更。
57	 *   表达式支路（collectDependencies 读代理自动收集）无此概念，声明了也不生效。
58	 */
59	export interface ScopeWatchOptions {
60	    depth?: number;
61	}
62	
63	/**
64	 * x-for 分页状态的只读快照（ADR-0042 分页状态读取器 `scope.paging`）。
65	 * total 为估算值（pageCount×pageSize，尾页不满时高估）。
66	 */
67	export interface AutoSparkPagingSnapshot {
68	    /** 当前页码（1-based） */
69	    page: number;
70	    /** 每页条数 */
71	    pageSize: number;
72	    /** 总页数（0=未知，load-more 模式） */
73	    pageCount: number;
74	    /** 是否还有下一页 */
75	    hasMore: boolean;
76	    /** 是否正在加载（loader 模式） */
77	    loading: boolean;
78	    /** 错误信息（loader 模式，无错为 null） */
79	    error: string | null;
80	    /** 总条数估算值（pageCount×pageSize） */
81	    total: number;
82	}
83	
84	/**
85	 * Q: 为什么要引入 Scope？
86	 * A: 一个 DOM 元素上可能挂多个指令，Scope 统一管理它们的生命周期与订阅，
87	 *    并在元素更新/销毁时集中清理（off watcher、递归销毁子作用域）。
88	 */
89	export class AutoSparkScope {
90	    /** scope 自增 id 计数器：作为 store.state.$scopes[id] 的索引键（x-data 私有响应式域，见 DataDirective） */
91	    private static _seq = 0;
92	    /** 本 scope 唯一标识；仅 x-data scope 会在 store.state.$scopes[id] 创建对应条目，其余 scope 不占位 */
93	    readonly id: number;
94	    private _template: WeakRef<HTMLElement>;
95	    /** 引用实际渲染的元素 */
96	    readonly _el: WeakRef<HTMLElement>;
97	    readonly engine: AutoSpark;
98	    directives: AutoSparkDirectiveBase[] = [];
99	    /**
100	     * 元素级宿主选项（`x-options` 解析产物，ADR-0007）。
101	     *
102	     * 供同元素所有指令经 `getOption` 回退读取（指令选项未命中时回退到此）。
103	     * 是配置而非数据，**不参与 getContext 聚合视图**（不污染表达式数据命名空间）。
104	     * 无 x-options 时为 null。
105	     */
106	    hostOptions: Record<string, any> | null = null;
107	    /**
108	     * x-data 注入的私有响应式数据域（指向 `store.state.$scopes[scope.id]`）。
109	     *
110	     * 由 `DataDirective` 在 `created()` 首次注入时令本字段指向 `store.state.$scopes[id]`（core 自动
111	     * 建响应式代理）。**永不换引用**——`_scopeView` Proxy 闭包绑定该引用；运行时更新只 `Object.assign`
112	     * 原地改（见 `engine.data`），绝不整体替换。与 `locals` 同级叠加进 `getContext`。
113	     *
114	     * 读写经 store 响应式代理 → `collectDependencies` 收集 `$scopes.<id>.<field>` 精准路径，
115	     * 字段级细粒度更新（**响应式**，无需 refresh——与 locals 的 refresh 驱动不同）。
116	     *
117	     * 父子元素的 data 经 parent 链层叠（子覆盖父同名键）；容器 x-data 经 parent 链
118	     * 自动透传进 x-for 各 item scope（item.parent = 容器 scope）。
119	     *
120	     * 字段名 `_data`（ADR-0022 决策二-3 修订）：对外暴露 `data` 改为 getter 返回 `getContext()`
121	     * 聚合视图（供 Proxy this 的 `this.data`），引擎内部读写响应式域用 `_data`。
122	     */
123	    _data: Record<string, any> | null = null;
124	    /**
125	     * data 聚合视图 getter（ADR-0022 决策二-3 修订）。
126	     *
127	     * 返回 `getContext()`——locals + _data + parent 链 + 全局 state 的聚合 Proxy 视图（响应式、
128	     * 可读可写）。供 Proxy this 的 `this.data`、外部便捷访问。底层响应式域经 `_data` 字段访问。
129	     */
130	    get data(): Record<string, any> {
131	        return this.getContext();
132	    }
133	    /**
134	     * 组件实例的内部方法容器（ADR-0022 决策二-3 修订）。
135	     *
136	     * 由 `<script setup>` 的 methods 经 `injectComponentSemantics` 注入（不再进 `scope.actions`，
137	     * 与 action 彻底分离）。method 经 `getMethod`（组件边界）查找、`getMethodThis()`（Proxy）调用——
