493	        this._methodThis = new Proxy(scope, {
494	            get(_t, k: string | symbol) {
495	                if (typeof k !== "string") return Reflect.get(scope, k);
496	                switch (k) {
497	                    case "data":
498	                        return scope.getContext();
499	                    case "state":
500	                        return scope.engine.state;
501	                    case "engine":
502	                        return scope.engine;
503	                    case "scope":
504	                        return scope;
505	                    case "el":
506	                        return scope.el;
507	                    case "$parent":
508	                        // 沿链找最近 isComponent 祖先的 Proxy（链式：其 get 陷阱递归处理 $parent）
509	                        return scope._parentComponentProxy();
510	                    default:
511	                        break;
512	                }
513	                // method 优先（组件边界）：this.inc() / this.other() 互调。
514	                // method 必须以其**所属组件实例**（getMethod 命中的那个 scope）的 Proxy 为 this——
515	                // 否则从子 scope 的 Proxy 取 method 时，this 会错绑成子 scope 的 Proxy。
516	                const owner = scope._findMethodOwner(k);
517	                if (owner) {
518	                    return owner.methods![k]!.bind(owner.getMethodThis());
519	                }
520	                // 组件响应式 data 域（_data）优先于 _locals（ADR-0022 决策二-3 (10)：Q2 data 优先）。
521	                // 直接判 _data（聚合视图 Proxy 的 hasOwnProperty 不走 has 陷阱，不可靠）。
522	                if (scope._data && Object.prototype.hasOwnProperty.call(scope._data, k)) {
523	                    return scope._data[k];
524	                }
525	                // 组件局部变量 _locals：非响应式、不进聚合视图。仅 method/钩子经 this.<key> 访问。
526	                if (scope._locals && Object.prototype.hasOwnProperty.call(scope._locals, k)) {
527	                    return scope._locals[k];
528	                }
529	                // 其余经聚合视图（x-for locals / parent 链 / 全局 state），支持 this.x 取模板可见的变量
530	                const view = scope.getContext();
531	                if (typeof k === "string" && k in view) {
532	                    return view[k];
533	                }
534	                // scope 原生方法/字段（watch/read/getComponent/getAction/...）
535	                const native = Reflect.get(scope, k);
536	                return typeof native === "function" ? (native as any).bind(scope) : native;
537	            },
538	            has() {
539	                return true; // 让 with(this) 与存在性检查一致
540	            },
541	            set(_t, k: string | symbol, val: any): boolean {
542	                if (typeof k === "string" && FRAMEWORK_KEYS.has(k)) {
543	                    scope.engine.logger.warn(
544	                        `组件 method/hook 内禁止整体覆盖框架引用 "${k}"（如需改数据请逐字段：this.data.${k} = ...）`,
545	                    );
546	                    return true; // 静默忽略（不真写入，也不报错）
547	                }
548	                // 组件响应式 data 域（_data）已有键 → 写 _data（响应式，Q2 data 优先）。
549	                if (typeof k === "string" && scope._data && Object.prototype.hasOwnProperty.call(scope._data, k)) {
550	                    scope._data[k] = val;
551	                    return true;
552	                }
553	                // 组件局部变量 _locals：声明键与新键均写 _locals（非响应式，如 this.timer = setInterval）
554	                if (typeof k === "string" && scope._locals) {
555	                    scope._locals[k] = val;
556	                    return true;
557	                }
558	                // 无 _data/_locals（非组件实例 scope）：透传聚合视图兜底
559	                try {
560	                    (scope.getContext() as any)[k] = val;
561	                } catch {
562	                    /* 聚合视图 set 失败静默 */
563	                }
564	                return true;
565	            },
566	        });
567	        return this._methodThis;
568	    }
569	
570	    /**
571	     * 沿 parent 链找最近的 `isComponent` 祖先，返回其 Proxy this（`$parent` 实现）。
572	     * 无父组件（已是顶层组件）返回 null。
573	     */
574	    private _parentComponentProxy(): any {
575	        let s = this.parent;
576	        while (s) {
577	            if (s.isComponent) return s.getMethodThis();
578	            s = s.parent;
579	        }
580	        return null;
581	    }
582	
583	    /**
584	     * 创建指令实例（按优先级降序排列，大的先执行）。
585	     */
586	    private _createDirectives() {
587	        const directiveDefine = getDirectives(this.template as HTMLElement);
588	        // createDirectives 内部已按静态 priority 降序排列，无需在此再排序
589	        this.directives = createDirectives(this.engine, directiveDefine, this);
590	        // 元素级宿主选项（x-options）：解析挂 scope，供同元素指令经 getOption 回退读取（ADR-0007）
591	        this.hostOptions = getHostOptions(this.template as HTMLElement) ?? null;
592	    }
593	
594	    /**
595	     * 订阅状态变化。双轨：
596	     *
597	     * - **路径支路**（`isStatePath` 为真，如 `user.name`）→ `store.watch(path)` 精准订阅，最快；
598	     * - **表达式支路**（如 `a + b`、x-for 内的 `item.name`）→ `collectDependencies` 自动收集读依赖后订阅。
599	     *
600	     * **为何表达式不走 `computedObjects.create`**：core 强制该 API 的 scope 只能是根/绝对路径，
601	     * 无法注入 x-for 的局部 `item`（见 core `computed/computedObjects.ts`）。
602	     * 故在此用 `store.collectDependencies` + `store.watch(deps)` 自建，与 core 的 `SyncComputedObject` 同构。
603	     *
604	     * 两条支路都把回调经 `engine.scheduler` 微任务合并：watcher 仅"标脏"，
605	     * flush 时重新求值并 patch——同 tick 多次变更只更新一次。
606	     *
607	     * @returns 当前值（供指令 `compile` 初始渲染）
608	     */
609	    watch(value: string, listener: ScopeWatchListener, options?: ScopeWatchOptions): any {
610	        // 有局部数据（自身或祖先的 locals/data）时，变量可能来自局部作用域
611	        // （如 x-data 的 a、x-for 的 item），不能按 state 路径直接订阅——统一走表达式支路
612	        // （经 getContext 聚合 locals+data+state 求值）。
613	        if (!this.hasLocalContext() && isSimpleStatePath(value)) {
614	            return this.watchPath(value, listener, options);
615	        }
616	        // 表达式支路无 depth 概念（读代理按实际读取收集依赖），options 被忽略
617	        return this.watchExpression(value, listener);
618	    }
619	
620	    /**
621	     * 路径支路：精准订阅指定路径（支持 core 通配符，如 `items.*` 单层、`items.**` 递归）。
622	     *
623	     * - 纯路径走 `store.watch(path)` 精准订阅，最快；
624	     * - path 含通配符时，`read()` 返回值无意义（getVal 取不到通配段），调用方应忽略返回值、
625	     *   仅依赖回调触发（如 x-for 监听 `items.*` 仅用于触发 render）。
626	     *
627	     * 公开供 x-for 等指令订阅通配路径——`scope.watch` 对含 `*` 的路径会误判为表达式走
628	     * `with` 求值（`with(scope){return items.*}` 语法错），故通配须绕开表达式支路直连此处。
629	     *
630	     * `options` 透传给 `store.watch`（如 `depth` 后代钻取深度，供属性展开订阅对象内部键变更，ADR-0043）。
631	     */
632	    watchPath(path: string, listener: ScopeWatchListener, options?: ScopeWatchOptions): any {
633	        const store = this.engine.store;
634	        const read = () => getVal(store.state, path);
635	        const update = () => listener({ value: read() });
636	        this._updates.push(update);
637	        this.watchers.push(
638	            store.watch(path, () => this.engine.scheduler.schedule(update), options),
639	        );
640	        return read();
641	    }
642	
643	    /**
644	     * 表达式支路：collectDependencies 自建。
645	     *
646	     * 1. `new Function` 把表达式编译为带 `scope` 形参的 getter；
647	     * 2. 在聚合作用域上求值一次，期间由 `collectDependencies` 收集读依赖；
648	     * 3. 用收集到的依赖路径订阅，回调仅标脏，flush 时重新求值。
649	     *
650	     * **宽松求值**：getter 抛错（如引用了不存在的局部变量 `a`、x-data 键被运行时删除）时，
651	     * 记日志并返回 `undefined`——与路径支路读不到键返回 `undefined` 行为一致，避免单个坏表达式
652	     * 中断整个编译/刷新。`collectDependencies` 用同一安全包装：抛错前已读到的依赖仍被收集。
653	     */
654	    private watchExpression(expr: string, listener: ScopeWatchListener): any {
655	        const store = this.engine.store;
656	        const scope = this.getContext();
657	        // 用 with(scope) 把作用域属性暴露为表达式变量，使 `user.first` 能解析到 scope.user.first。
658	        // new Function 默认松散模式支持 with；scope 是聚合 Proxy，has/get 陷阱联动 store.state。
659	        const getter = new Function("scope", "args", `with(scope){ return (${expr}); }`) as (
660	            scope: any,
661	            args?: any,
662	        ) => any;
663	        const safeEval = (): any => {
664	            try {
665	                return getter(scope);
666	            } catch  {
667	                //this.engine.logger.warn(`scope.watch: eval "${expr}" failed: ${e?.message ?? e}`);
668	                return undefined;
669	            }
670	        };
671	        // 首次求值与依赖收集合并为一次：在 collectDependencies 的求值回调内缓存结果，
672	        // 末尾直接返回缓存值——避免再 safeEval() 一次造成的重复求值与重复告警。
673	        // （flush 时 update 闭包仍每次重新求值，那是必要的。）
674	        let firstValue: any;
675	        let deps = store.collectDependencies(() => {
676	            firstValue = safeEval();
677	        }, "read");
678	        // 动态依赖重收集：短路（|| / && / ?:）与条件分支使不同分支读不同键，依赖集随实际
679	        // 走到的分支漂移（如 `a || b` 在 a 真时初收集只含 a）。若只在首求值收集一次，
680	        // 漂移后旧分支键的变化不再通知——典型受害者：`x-if="loaded && items.length"`、
681	        // `:disabled="page <= 1 || $loading"`（page 同时是重取触发器时短路键永远收不到回落）。
682	        // 故 update 重求值时重新收集，漂移则重订 watcher（Vue effect 同款策略；同一状态同一
683	        // 分支的 deps 稳定，重订自然收敛，无循环风险）。
684	        let watcher: Watcher = store.watch(deps, () => this.engine.scheduler.schedule(update));
685	        const update = () => {
686	            let value: any;
687	            const nextDeps = store.collectDependencies(() => {
688	                value = safeEval();
689	            }, "read");
690	            listener({ value });
691	            if (!depsEqual(deps, nextDeps)) {
692	                watcher.off();
693	                const idx = this.watchers.indexOf(watcher);
694	                if (idx >= 0) this.watchers.splice(idx, 1);
695	                deps = nextDeps;
696	                watcher = store.watch(deps, () => this.engine.scheduler.schedule(update));
697	                this.watchers.push(watcher);
698	            }
699	        };
700	        this._updates.push(update);
701	        this.watchers.push(watcher);
702	        return firstValue;
703	    }
704	
705	    /**
706	     * 同步重跑本作用域注册的全部 update 闭包，并递归刷新所有子作用域。
707	     *
708	     * 用途：x-for 复用项时，项内 locals 字段（item / $index / $end 等）已原地更新，
709	     * 需让项内全部绑定（含 `$end` 这类订阅为空、store 不会自动触发的 watcher）重新求值并 patch DOM。
710	     *
711	     * 同步直跑、不进 scheduler：render 自身已在 scheduler flush 内执行，update 闭包内的 listener
712	     * 直接 patch DOM，避免双重调度；同步也保证 render 返回时 DOM 已是最新。
713	     *
714	     * 递归 children 覆盖项内嵌套 x-for（触发其 render）、eager x-if 子树、x-text 等所有子绑定。
715	     * 已 destroy 的子作用域已从 children 移除，自然跳过。
716	     */
717	    refresh(): void {
718	        for (const update of this._updates) {
719	            try {
720	                update();
721	            } catch (e: any) {
722	                this.engine.logger.error(e);
723	            }
724	        }
725	        for (const child of this.children) {
726	            child.refresh();
727	        }
728	    }
729	
730	    /**
731	     * 读取表达式/路径的当前值（不建立订阅）。
732	     *
733	     * 供 x-for 等"已在 `created` 自行订阅、仅需在回调中重读最新值"的指令使用。
734	     * 求值方式与 `watch` 保持一致：纯路径走 `getVal`，否则走 `with(scope)` 表达式求值
735	     * （使 `items.filter(x => x.active)` 这类表达式能取到经筛选/映射后的数组，
736	     * 而非被 `getVal` 当作点分路径读成 undefined）。
737	     *
738	     * @returns 表达式当前值；求值异常时记录日志并返回 undefined（由调用方做数组化等兜底）
739	     */
740	    read(value: string): any {
741	        if (!this.hasLocalContext() && isSimpleStatePath(value)) {
742	            return getVal(this.engine.store.state, value);
743	        }
744	        const scope = this.getContext();
745	        const getter = new Function("scope", `with(scope){ return (${value}); }`) as (
746	            scope: any,
747	        ) => any;
748	        try {
749	            return getter(scope);
750	        } catch  {
751	            //this.engine.logger.warn(`scope.read: eval "${value}" failed: ${e?.message ?? e}`);
752	            return undefined;
753	        }
754	    }
755	
756	    /**
757	     * 编译：依次执行指令的 `created`（建立订阅）→ `compile`（初始渲染）。
758	     *
759	     * `created` 必须先于 `compile` 执行——`watch` 在 created 中建立，
760	     * 随后 compile 用 `watch` 返回的当前值做首次 DOM 写入。
761	     */
762	    compile() {
763	        // 组件实例：created 在指令 created/compile 之前触发（data 已注入、DOM 子树尚未编译）
764	        this._runHooks("created");
765	        this.runDirectives(this.directives);
766	        this.engine.emit("scope/compiled", { id: this.id });
767	        // 组件实例：mounted 在 DOM 子树编译完成后触发
768	        this._runHooks("mounted");
769	    }
770	
771	    /**
772	     * 串行执行某阶段的组件生命周期钩子（ADR-0022 决策三 + 决策二-3 修订）。
773	     *
774	     * 每个 hook 用 `getMethodThis()` 返回的 **Proxy** 作 this（与 method 的 this 完全统一：
775	     * data=getContext 视图、state、engine、scope、method 名直调、$parent 等）。单个 hook 抛错
776	     * try-catch 记 error 不阻断后续 hook（容错）。hooks 为 null（非组件 scope）或该阶段无 hook
777	     * 时静默无副作用。
778	     */
779	    private _runHooks(phase: "created" | "mounted" | "beforeUnmount" | "unmounted"): void {
780	        const fns = this.hooks?.[phase];
781	        if (!fns || fns.length === 0) return;
782	        const ctx = this.getMethodThis();
783	        for (const fn of fns) {
784	            try {
785	                fn.call(ctx);
786	            } catch (e: any) {
787	                this.engine.logger.error(
788	                    `x-component hook "${phase}" 执行失败: ${e?.message ?? e}`,
789	                );
790	            }
791	        }
792	    }
793	
794	    /**
795	     * 串行执行指令生命周期：先全部 created，再全部 compile。
796	     * 同一阶段的指令按优先级顺序（已由 `_createDirectives` 排好）。
797	     */
798	    runDirectives(directives: AutoSparkDirectiveBase[]): void {
799	        for (const d of directives) {
800	            if (typeof d.created === "function") d.created();
801	            this.engine.emit(("directive/" + d.info.name + "/created") as any, {
802	                name: d.info.name,
803	                id: this.id,
804	            });
805	        }
806	        for (const d of directives) {
807	            if (typeof d.compile === "function") d.compile(this.engine.state, this.el!);
808	            this.engine.emit(("directive/" + d.info.name + "/compiled") as any, {
809	                name: d.info.name,
810	                id: this.id,
811	            });
812	        }
813	    }
814	
815	    /**
816	     * 销毁：先从父级脱离，再递归销毁子作用域（子树 watcher 批量 off），
817	     * 然后 off 自身 watcher，最后触发各指令的 destroy 钩子。
818	     */
819	    destroy() {
820	        try {
821	            // 组件实例：beforeUnmount 在 watcher off 之前触发（watcher 仍活，可读最终状态做精确清理）
822	            this._runHooks("beforeUnmount");
823	            // 从父级 children 移除自身：否则 x-for 全量重建 / x-if 子树切换时，旧项 scope 虽
824	            // 已 destroy（watcher 已 off），却仍残留在父 children Set 中 → 僵尸 scope 永久驻留（内存泄漏）。
825	            // Set 迭代中删除「当前元素」安全（既不跳过后续、也不重复访问）。
826	            this.parent?.children.delete(this);
827	            for (const child of this.children) {
828	                child.destroy();
829	            }
830	            this.children.clear();
831	            for (const watcher of this.watchers) {
832	                watcher.off();
833	            }
834	            this.watchers.length = 0;
835	            this._updates.length = 0;
836	            for (const d of this.directives) {
837	                if (typeof d.destroy === "function") d.destroy(this.el!);
838	                this.engine.emit(("directive/" + d.info.name + "/destroyed") as any, {
839	                    name: d.info.name,
840	                    id: this.id,
841	                });
842	            }
843	            // 组件实例：unmounted 在指令 destroy 之后、scope/destroyed 之前触发（收尾）
844	            this._runHooks("unmounted");
845	        } catch (e: any) {
846	            this.engine.logger.error(e);
847	        }
848	        this.engine.emit("scope/destroyed", { id: this.id });
849	    }
850	}
