            this.engine.animate.cancel(this.el!);
        }
        if (this.el) {
            // 单例隐藏态复活（DOM+scope 保活）：重注入 params + 重新显示（anchor 每次显示现算）
            this._applyParams(params);
            this._show();
            return;
        }
        this._buildAndMount(params);
