describe("配置合并与类型校验", () => {
    test("四级深度合并：x-overlay-options < x-dialog-options < 值对象内联", async () => {
        const { engine } = mountOverlay(
            `<div id="app"><div x-scope>
                <div x-overlay:mix="dialog" x-overlay-options="{closeOnMask: false, singleton: false}"><span>x</span></div>
