describe("生命周期挂链（scope 基准三合一）", () => {
    test("consumer 基准：消费者随 x-if 销毁 → 打开中的实例级联强拆", async () => {
        const { root, engine } = mountOverlay(
            `<div id="app"><div x-scope>
                <div x-overlay:tmp="dialog"><span>x</span></div>
                <div x-if="ui.show">
